import{c as e}from"./BYVJS2Dj.js";const i={lang:"de",meta:{title:`${e.brand} — KI, die Ihnen die Routinearbeit abnimmt`,description:"Kleine KI-Werkzeuge für Anwälte, Lehrkräfte, Zahnärzte, Gutachter und andere Berufstätige in Berlin. Wir übernehmen Papierkram, Sortieren und Nachfassen. Jede Entscheidung bleibt bei Ihnen. Das Erstgespräch ist kostenlos."},nav:{contact:"Kontakt",menu:"Menü"},hero:{availability:"Wir nehmen neue Kunden an",headline:"Die Routinehälfte Ihrer Woche kann von allein laufen.",subline:`${e.brand} baut kleine KI-Werkzeuge für Praxen, Teams und Selbstständige. Wir übernehmen den Papierkram, das Sortieren und das Nachfassen, die Ihre Abende auffressen. Den Teil, der Ihr Urteil braucht, fassen wir nicht an. Jede Entscheidung bleibt bei Ihnen.`,button:"Kostenloses Erstgespräch vereinbaren",note:"Berlin · inhabergeführt, vom ersten Gespräch bis zur Übergabe"},studio:{worksLabel:"Beispiele aus der Praxis",capabilitiesLabel:"So arbeiten wir",bookLabel:"Kostenloses Erstgespräch",bookTitle:"Wählen Sie eine Zeit, die Ihnen passt.",bookNote:"Dreißig Minuten, kostenlos, keine Vorbereitung nötig.",workBack:"Alle Beispiele",worksHeading:"Was KI für Menschen wie Sie schon erledigt.",worksIntro:"Jedes Beispiel hier haben wir selbst gebaut und betrieben, für echte Menschen mit echten Fristen. Jedes zeigt, was das Werkzeug übernommen hat, was bei der Person geblieben ist und wo wir die Grenze gezogen haben. Wählen Sie das, was Ihrer Arbeit am nächsten kommt.",worksMeta:`Echte Beispiele für KI im Arbeitsalltag: Vertragsprüfung für Anwälte, Korrektur für Lehrkräfte, Recall für Zahnärzte, Wohnungssuche, Jobsuche, Forschung und Prüfungsvorbereitung. Gebaut von ${e.brand}, KI-Beratung in Berlin.`,workName:"Für wen",workPeople:"Begleitete Menschen",workCovers:"Was es übernimmt",workMachinery:"Was das System übernimmt",workJudgement:"Was bei Ihnen bleibt",workBuilds:"Was wir bauen",workStops:"Wo es aufhört",workProof:"Woran Sie den Erfolg sehen",workRefuse:"Wann wir Nein sagen",workCost:"Was es von Ihnen verlangt",bookCta:"Oder schreiben Sie uns",close:"Schließen",priceLabel:"Was es kostet"},who:{eyebrow:"Für wen wir arbeiten",rosterEyebrow:"Seit 2022",rosterTitle:"Mit wem wir tatsächlich gearbeitet haben.",rosterIntro:"Keine Zielgruppe. Das sind die Berufe, in deren Arbeitswoche wir schon gesessen haben, eine Person nach der anderen. Wählen Sie den, der Ihrem am nächsten kommt.",statPeople:"Begleitete Menschen",statFields:"Berufsfelder",roster:{"job-seekers":"Jobsuchende",athletes:"Sportler","content-creators":"Content-Creator","home-buyers":"Immobilienkäufer",lawyers:"Anwälte",teachers:"Lehrkräfte",coaches:"Coaches & Yogalehrende","product-managers":"Produktmanager","online-shoppers":"Online-Käufer",architects:"Architekten","project-managers":"Projektleiter",surveyors:"Gutachter","event-organizers":"Veranstalter",dentists:"Zahnärzte","team-leaders":"Teamleitungen","estate-agents":"Immobilienmakler",executives:"Führungskräfte",chefs:"Küchenchefs","volunteer-orgs":"Vereine"},notListed:"Ihr Beruf ist nicht dabei? Es passt mit großer Wahrscheinlichkeit trotzdem. Fragen Sie uns."},method:{label:"Wie wir entscheiden, was wir bauen",title:"Wie wir entscheiden, was wir bauen — KI-Beratung Berlin",metaDescription:"Eine Frage entscheidet alles: Welcher Teil Ihrer Woche ist Routinearbeit, und welcher braucht Ihr Urteil? Die vier Tests, die vier Schritte jedes Projekts und die fünf Gründe, aus denen wir Nein sagen.",headline:"Welcher Teil Ihrer Woche wiederholt sich, und welcher braucht Sie?",intro:["Jeder Mensch, mit dem wir gearbeitet haben, kam mit einer anderen Berufsbezeichnung und demselben Satz: Ein Teil meiner Woche ist unerträglich geworden. Der Beruf wechselt. Die Form des Problems fast nie.","Wir fragen nicht, was Sie automatisieren wollen, denn das weiß fast niemand. Sie wissen, was wehtut. Unsere Aufgabe ist, die genaue Grenze zu finden zwischen der Arbeit, die sich wiederholt, und der Arbeit, die Ihr Urteil braucht, und nur auf der Routineseite zu bauen. Diese Grenze zu finden ist der schwere Teil. Das Werkzeug zu bauen ist der leichte."],testsTitle:"Wie wir das eine vom anderen unterscheiden.",machineryLabel:"Routinearbeit — alle vier müssen zutreffen",machinery:["Es wiederholt sich. Öfter als einmal pro Woche, in ungefähr derselben Form.","Es folgt Regeln. Müssten Sie erklären, wie Sie es tun, könnten Sie es, in Sätzen und nicht in Gesten.","Es ist leicht zu prüfen. Ein falsches Ergebnis erkennen Sie in Sekunden.","Ein entdeckter Fehler kostet wenig. Irrt sich das Werkzeug und Sie merken es, verlieren Sie eine Minute, nicht mehr."],judgementLabel:"Ihr Urteil — eines davon genügt",judgement:["Sie haften dafür. Ihr Name, Ihre Zulassung oder Ihre Unterschrift steht darunter.","Ihr Geschmack ist das Produkt. Man bezahlt Sie genau dafür, dass die Sicht Ihre ist.","Die Beziehung ist das Produkt. Eine Patientin, ein Schüler, eine Mandantin, ein Publikum.","Es ist eine echte Entscheidung unter Unsicherheit, kein Nachschlagen mit Zwischenschritten."],seam:"Wir bauen bis an diese Grenze und nie darüber hinaus. Fast jedes gescheiterte KI-Projekt, das wir retten sollten, ist gescheitert, weil jemand über die Grenze hinaus gebaut hat und der Mensch den Ergebnissen still nicht mehr vertraute.",refuseTitle:"Wann wir Nein sagen.",refuseIntro:"Wir sagen laut Nein und behalten die Beziehung. Nein zu sagen ist der Hauptgrund, warum Menschen uns ihre Bekannten und Kollegen schicken.",refuse:[{title:"Es ist zu wenig davon.",text:"Unter etwa einer Stunde pro Woche kostet es mehr, ein Werkzeug am Laufen zu halten, als die Aufgabe selbst."},{title:"Jeder Fall ist anders.",text:"Gleicht kein Fall dem anderen, gibt es nichts Wiederkehrendes zu übernehmen. Es gibt nur Können, und Können ist kein Engpass, den man beseitigt."},{title:"Ein Fehler wäre zu teuer.",text:"Könnte ein einziges falsches Ergebnis eine Laufbahn beenden, bereitet das Werkzeug das Material vor und tut sonst nichts."},{title:"Ein einfaches Werkzeug gibt es schon.",text:"Ein Kalender, ein Formular, eine geteilte Tabelle, eine Vorlage. Das richten wir ein und berechnen den Nachmittag, nicht das Quartal."},{title:"Es ist eine Entscheidung, keine Arbeitslast.",text:"Manche brauchen kein System. Sie müssen etwas entscheiden, das sie vor sich herschieben. Keine Software behebt das."}],registersTitle:"Zwei Arten von Erfahrung.",registersText:`Unser Inhaber ${e.name} betreibt in einem Unternehmen ein KI-System, das eine echte Rechtsabteilung jeden Tag nutzt. Bei ${e.brand} sitzen wir mit einer Yogalehrerin oder einem Küchenchef am Küchentisch. Die Unternehmensarbeit lehrt uns, was Prüfungen, Übergaben und Kollegen übersteht, die nie nach dem Werkzeug gefragt haben. Die Einzelarbeit hält uns ehrlich darüber, wie wenig die meisten wirklich brauchen.`,casesCta:"Die Beispiele ansehen"},built:{items:[{slug:"job-seekers",title:"KI für Jobsuchende: weniger, bessere Bewerbungen — KI-Coaching Berlin",metaDescription:"Ein Werkzeug, das die ganze Stellenanzeige liest, mit Ihrer echten Erfahrung abgleicht und nie schönt. Dreißig Menschen sind so in Arbeit.",label:"Jobsuche",headline:"Dreißig Menschen sind über diesen Weg in Arbeit.",story:["Keine „Jobsuchenden“. Ein Logistikkoordinator, dessen Lager geschlossen wurde. Eine Frau, die nach drei Jahren mit Kindern zurückkommt und die Lücke für disqualifizierend hält. Ein Entwickler mit ablaufendem Visum. Eine Absolventin, die 180 Bewerbungen geschickt hat und die Antworten nicht mehr öffnet. Sie kommen gedemütigt an, und um die Demütigung kümmern wir uns zuerst.","Es ist nie eine Stunde, es ist jeder Abend. Derselbe Lebenslauf geht an hundert Anzeigen, im Anschreiben wird nur der Firmenname getauscht. Es kommt nichts zurück, also schicken sie mehr. Menge ersetzt Nachdenken, Nachdenken hätte die Menge ersetzt, und die Schleife zieht sich zu, bis sie nicht mehr hinsehen können."],machinery:["Eine Anzeige ganz lesen und herausziehen, was wirklich verlangt wird — auch die Anforderung, die in Absatz vier steht","Diese Anforderungen mit einer festen Liste dessen abgleichen, was Sie tatsächlich getan haben","Lebenslauf und Anschreiben für genau diese Anzeige erstellen, Beleg für Beleg","Jede Bewerbung im Blick behalten: Stand, Datum, wann nachgefasst werden muss","Das Vorbereitungspaket für genau dieses Gespräch zusammenstellen","Wiederveröffentlichte Anzeigen, Phantomanzeigen von Agenturen und Dubletten erkennen"],judgement:["Ob diese Stelle erstrebenswert ist","Wie Sie über die Lücke, die Kündigung, das Visum sprechen","Was Sie über sich behaupten und was nicht","Ob Sie das Angebot annehmen"],builds:[{name:"Der Belegspeicher",text:"Die erste Sitzung ist keine Software. Wir setzen uns zusammen hin und schreiben auf, was Sie tatsächlich getan haben — mit Zahlen, in Ihren eigenen Worten. Meist zwei bis vier Stunden, und es ist der schwerste Teil. Nichts kommt ins System, was nicht aus diesem Speicher stammt."},{name:"Der Anzeigenleser",text:"Link oder PDF einfügen. Zurück kommen die echten Anforderungen, getrennt in hart und weich, was die Anzeige über das Team verrät, und ein Absatz in normaler Sprache dazu, was diese Stelle wirklich ist."},{name:"Der Abgleich",text:"Jede Anforderung bekommt eine von drei Markierungen: belegt, benachbart oder fehlend. Fehlend bleibt fehlend. Das Werkzeug erfindet nie eine Brücke."},{name:"Der Bewerbungs-Tracker",text:"Eine Zeile pro Bewerbung: Stelle, Datum, Quelle, Stand, Nachfassdatum, Ergebnis und was Sie daraus gelernt haben. Nach dreißig Bewerbungen ist das Ihr wertvollster Besitz, weil die Muster sichtbar werden — welche Branchen antworten, welche Kanäle tot sind, welche Aussagen Gespräche bringen."},{name:"Das Vorbereitungspaket",text:"Für jedes Gespräch zusammengestellt, aus Anzeige und Belegspeicher: wahrscheinliche Fragen, Ihre eigenen Beispiele passend dazu, und Fragen, die Sie selbst stellen können."}],stops:{title:"Das Werkzeug weigert sich, Ihre Erfahrung zu übertreiben.",text:["Das ist keine Einstellung. Fehlt eine Anforderung, sagt es fehlend und lässt Ihnen die Wahl: Bewerbung auslassen oder die Lücke im Anschreiben ehrlich ansprechen. Wir sind gebeten worden, das abzuschwächen. Wir tun es nicht.","Es ist der Grund, warum die dreißig Menschen ihre Stellen behalten haben — im Gespräch wurde nichts versprochen, was am Montag nicht lieferbar war. Es entscheidet auch nicht, wo Sie sich bewerben. Es sortiert und filtert; Sie wählen."]},proof:"Nicht die Zahl der Bewerbungen — die sinkt, meist um 70%. Wir zählen: Gespräche pro hundert Bewerbungen, Zeit von der Anzeige bis zur abgeschickten Bewerbung (Ziel: unter 25 Minuten) und tatsächlich verschickte Nachfassnachrichten.",refuse:"Wenn Sie kein Bewerbungsproblem haben, sondern eine Berufsentscheidung vor sich herschieben — Sie wissen, dass das Feld falsch ist, und bewerben sich trotzdem darin. Kein Werkzeug behebt das, und eines zu bauen hilft Ihnen nur beim Aufschieben.",cost:"Der Belegspeicher tut weh: zwei bis vier Stunden ehrliche Antworten darauf, was Sie tatsächlich getan haben. Alles danach sind fünfzehn Minuten pro Bewerbung.",quotes:[{text:"Ich hatte hundertachtzig Bewerbungen geschickt und die Antworten irgendwann nicht mehr geöffnet. Die erste Sitzung war überhaupt keine Software, sondern vier Stunden, in denen er mich gefragt hat, was ich tatsächlich getan habe, und es aufgeschrieben hat — das fand ich schwerer als jedes Vorstellungsgespräch. Danach habe ich mich in sechs Wochen auf elf Stellen beworben statt auf vierzig, und drei haben angerufen. Am meisten ist mir aufgefallen, dass das Werkzeug mich nichts behaupten ließ, was ich nicht belegen konnte — ich wollte eine Zeile über ein System weicher formulieren, das ich kaum angefasst hatte, und es hat schlicht nein gesagt.",name:"Logistikkoordinator, Brandenburg"},{text:"Ich war drei Jahre mit meinen Kindern raus und war sicher, dass die Lücke der Grund war, warum niemand antwortet. Er hat mir nicht gesagt, die Lücke sei kein Problem — was ich geschätzt habe — er hat gesagt, sie sei ein Absatz, und wir haben den Absatz geschrieben. Der Tracker war das, von dem ich am wenigsten erwartet hätte, dass es zählt, und es hat am meisten gezählt: Nach zwanzig Bewerbungen sah ich, dass eine ganze Branche nie antwortet, und habe aufgehört, dort meine Abende zu verlieren.",name:"Projektassistentin, Berlin"}]},{slug:"athletes",title:"KI für Sportler: ein Highlight-Video in Minuten — KI-Coaching Berlin",metaDescription:"Spielaufnahmen in Szenen sortiert, ein Highlight-Video in Minuten statt an einem Abend, ein Profil für Scouts und ein Trainingslog, das warnt, aber nie vorschreibt.",label:"Sportler",headline:"Wenn ein Scout etwas sehen will, darf es nicht vier Tage dauern.",story:["Halbprofis und ernsthafte Amateure: ein Drittligafußballer, der eine Liga höher gesehen werden will, zwei Wettkampfkletterer, eine Handballerin nach dem Knie, ein E-Sportler, dessen Team sich auflöste, ein Triathlet, der sich selbst trainiert, weil der Trainer mehr kostet als die Startgelder. Fast alle führen ihre eigene Karriere als unbezahlten Zweitjob — mit schlechteren Werkzeugen, als ihr Arbeitgeber hat.","Meist sind es zwei Stunden, an denen es scheitert. Die erste ist das Material: 90 Minuten Spiel auf dem Handy, aus denen vier brauchbare Clips werden müssen — jede Woche ein Abend. Die zweite ist die Ansprache: E-Mails an Vereine, Scouts, Berater und Sponsoren, jede neu geschrieben, jede unbeantwortet, keine davon nachgehalten."],machinery:["Eine lange Aufnahme in benannte Szenen zerlegen — jede Aktion, jeder Satz, jede Runde, jede Wiederholung","Aus den Szenen, die Sie auswählen, ein Video bauen: richtige Länge, richtiges Format, richtige Untertitel für die Plattform, die ein Scout wirklich öffnet","Einheiten protokollieren — Belastung, Dauer, gefühlte Anstrengung, Schlaf, Muskelkater — und einen klaren Sieben-Tage-Trend zeigen","Ein einseitiges Profil für Scouts pflegen, das sich von selbst aktualisiert","Jeden kontaktierten Verein, Scout und Sponsor nachhalten, mit Nachfassdatum","Das gesprochene Feedback des Trainers in eine Notiz verwandeln, die Sie durchsuchen können"],judgement:["Ob der Körper heute passt","Was mit einem Zwicken zu tun ist","Welcher Verein, welcher Vertrag, welches Niveau","Die Technikkorrektur"],builds:[{name:"Der Szenenschnitt",text:"Sie laden Spiel oder Einheit hoch; zurück kommt alles nach Szenentyp sortiert, mit Zeitmarken. Sechs Szenen auswählen, und Sie haben ein fertiges Video im richtigen Format, mit Name, Position und Datum im Bild. Aus einem Abend werden etwa elf Minuten."},{name:"Das Trainingslog",text:"Bewusst langweilig: ein Handyformular mit fünf Feldern, zehn Sekunden nach jeder Einheit. Es zeichnet die Belastung dieser Woche gegen die Wochen davor und markiert scharfe Sprünge. Es markiert. Es verordnet nicht."},{name:"Die Profilseite",text:"Eine Seite, immer aktuell: Position, Alter, Größe, Saisonminuten, Kennzahlen, drei Clips, Kontakt. Der einzige Grund, warum Spieler nicht gesehen werden: Wenn ein Scout etwas anfordert, dauert das Zusammenstellen vier Tage — und dann ist das Interesse erkaltet."},{name:"Der Kontakt-Tracker",text:"Gebaut wie der Bewerbungs-Tracker, weil es dasselbe Problem im Trainingsanzug ist: eine Zielliste, eine aus echtem Material gebaute Nachricht, ein Nachfassdatum und ein Protokoll dessen, was zurückkam."},{name:"Das Comeback-Log",text:"Für die Reha: die Anweisungen der Physiotherapie einmal aufgeschrieben, die Einheiten dagegen protokolliert, und eine Wochenübersicht, die die Praxis in dreißig Sekunden liest."}],stops:{title:"Es verordnet nie eine Einheit und beurteilt nie eine Verletzung.",text:["Es zeigt den Trend und legt die Zahl dem Sportler vor und, sofern vorhanden, dem Trainer oder der Physiotherapie. Drei Anfragen nach einer „empfohlenen Belastung für morgen“ haben wir abgelehnt. Die Folge eines Fehlers ist jemandes Saison, und das Werkzeug kann das Knie nicht fühlen.","Es spricht auch nicht mit Vereinen. Entwürfe warten darauf, dass der Spieler sie selbst abschickt."]},proof:"Minuten vom Abpfiff bis zu einem Video, das ein Scout öffnen könnte. Kontaktierte Vereine, bei denen tatsächlich nachgefasst wurde. Und ob das Log acht Wochen später noch geführt wird — das ist der eigentliche Test, und deshalb hat das Formular fünf Felder.",refuse:"Wenn das Problem ist, dass jemand für dieses Niveau noch nicht gut genug ist. Das kommt vor, und kein Highlight-Video ändert daran etwas. Das ehrliche Gespräch darüber ist mehr wert als das System; wir haben es zweimal geführt.",cost:"Zehn Sekunden nach jeder Einheit für das Log. Zwanzig Minuten nach jedem Spiel für das Material.",quotes:[{text:"Jeden Sonntag ging ein Abend dafür drauf, aus neunzig Minuten Handyaufnahme vier Clips zu schneiden. Jetzt lade ich nach dem Spiel hoch, und bis ich gegessen habe, ist alles getaggt; ich wähle sechs Momente und habe in etwa zehn Minuten ein Video. Wirklich verändert hat etwas die Profilseite — als im August ein Scout „schick mir mal was“ sagte, habe ich es in derselben Stunde geschickt. Vorher hätte das vier Tage gedauert, und dann interessiert es niemanden mehr.",name:"Mittelfeldspieler, Regionalliga"},{text:"Ich trainiere mich selbst, weil ein Trainer mehr kostet als meine Startgelder — also habe ich meine Belastung in einem Notizbuch geführt und mich darin belogen. Fünf Felder auf dem Handy nach jeder Einheit, zehn Sekunden, und der Sieben-Tage-Trend wird für mich gezeichnet. Zwei Wochen vor einem Wettkampf hat es einen Sprung markiert und ich habe zurückgenommen. Es sagt mir nie, was ich tun soll, es legt mir nur die Zahl hin — und das reicht offenbar.",name:"Triathletin, Leipzig"}]},{slug:"content-creators",title:"KI für Content-Creator: Ihre Abende zurück — KI-Beratung Berlin",metaDescription:"Material abends in den Ordner, morgens liegen Transkript, Rohschnitt und acht Clip-Vorschläge bereit. Fünfzehn Minuten auswählen. Keine KI-Skripte, keine KI-Stimme.",label:"Content-Creator",headline:"Aus sechs Stunden zwischen Dreh und Veröffentlichung werden unter zwei.",story:["Ein Kochkanal, geführt von einer Person mit 60.000 Abonnenten. Ein Podcast-Duo. Ein deutscher Comedian mit Shorts. Zwei Bildungs-Creator. Eine Fotografin, die Behind-the-Scenes filmt. Keine Medienhäuser — Menschen, die gleichzeitig Talent, Cutter, Herausgeber und Kundendienst sind und die still kurz davor stehen, an den drei Jobs auszubrennen, die nicht der geliebte sind.","Der Dreh dauert zwei Stunden, der Schnitt sechs, die Untertitel eine, und Beschreibung, Tags, Thumbnail und Planung noch einmal eine. Sie sind nicht müde vom Machen. Sie sind müde von den Stunden zwischen „fertig gedreht“ und „online“."],machinery:["Alles transkribieren, genau, mit Zeitmarken und wer was gesagt hat","Stille, Füllwörter, Fehlstarts und den vierten Anlauf an einem Satz entfernen","Clip-Vorschläge machen, sortiert, mit Zeitmarke und Begründung","Untertitel in Ihrer Schrift, Position und Sprache einbrennen, plus SRT-Datei","Einen Masterschnitt in 16:9, 9:16 und 1:1 umformatieren — Sie bleiben im Bild","Beschreibung, Kapitel und Tags aus dem Transkript schreiben","Kommentare sortieren: Fragen, Beleidigungen, Geschäftsanfragen, Rest","Das Archiv pflegen, damit „hatte ich das schon?“ eine Antwort hat"],judgement:["Was witzig ist. Was wahr ist. Was gesagt gehört","Der Hook — die ersten drei Sekunden","Ob das überhaupt rausgeht","Die Stimme"],builds:[{name:"Der Rohschnitt über Nacht",text:"Das Tagesmaterial in einen Ordner legen. Über Nacht kommen ein Transkript, ein Rohschnitt ohne Stille und acht sortierte Clip-Vorschläge mit Begründung zurück — „Lacher bei 04:12“, „Frage sauber beantwortet bei 19:40“."},{name:"Die Viertelstunde Auswahl",text:"Sie setzen sich fünfzehn Minuten hin und wählen aus. Das ist Ihr gesamter Anteil an der Routinearbeit, und es ist bewusst der einzige Punkt, an dem Sie denken müssen."},{name:"Die fertigen Clips",text:"Gewählte Clips geschnitten, in Ihrem bestehenden Stil untertitelt — gleiche Schrift, gleiche Farbe, gleiche Platzierung, abgeschaut von dem, was Sie schon nutzen — pro Plattform umformatiert und mit Beschreibung, Kapiteln und Tags in einen Veröffentlichungsordner gelegt."},{name:"Die Kommentar-Sortierung",text:"Vier Körbe jeden Morgen. Geschäftsanfragen gehen in ein echtes Postfach. Beleidigungen in einen Ordner, den Sie nie öffnen müssen — außer Sie wollen Beweise."},{name:"Das Archiv",text:"Jedes Transkript durchsuchbar. Das ist der heimliche Gewinner: Nach zwei Jahren wissen die meisten nicht mehr, was sie gesagt haben, und das Archiv nimmt die Angst vor versehentlicher Wiederholung."}],stops:{title:"Es schreibt nicht den Inhalt und nicht in Ihrer Stimme.",text:["Keine KI-Skripte, kein synthetischer Sprecher, kein „im Stil von“. Der Grund ist wirtschaftlich wie ethisch: Die Stimme ist das gesamte Kapital. Wer seine Stimme erzeugbar macht, hat das Einzige verkauft, was ihm gehörte. Wir sagen das im ersten Gespräch und haben darüber einen Auftrag verloren.","Hooks bleiben menschlich. Für Thumbnails erzeugen wir Varianten Ihres eigenen Fotos — Ausschnitte, Textplatzierung — nie ein synthetisches Bild."]},proof:"Stunden zwischen „Dreh beendet“ und „veröffentlicht“ — typisch von rund sechs auf unter zwei. Uploads pro Woche ohne mehr Drehtage. Und das, was sechs Monate später ungefragt gesagt wird: Sie haben ihre Abende zurück.",refuse:"Wenn jemand nicht postet, weil er nichts zu sagen hat. Schnelleres Veröffentlichen macht das schnell und sichtbar schlimmer. Zweimal haben wir einem Creator gesagt, dass sein Problem vor dem Schnitt liegt.",cost:"Fünfzehn Minuten Auswählen am Morgen. Alles andere läuft, während Sie schlafen.",quotes:[{text:"Der Dreh dauerte zwei Stunden und alles danach sechs, und ich fing an, den Kanal zu hassen. Jetzt lege ich das Material vor dem Schlafen in einen Ordner, und morgens liegen ein Transkript da, ein Rohschnitt ohne tote Luft und acht Clips, die es für gut hält, mit einer Begründung an jedem. Er wollte nichts bauen, das in meiner Stimme schreibt, und hat im ersten Gespräch erklärt warum — er hatte recht, das ist das Einzige, was mir wirklich gehört.",name:"Kochkanal, 61.000 Abonnenten"},{text:"Das Archiv ist das, was niemand in einen Prospekt schreiben würde, und es ist das, was ich jede Woche benutze. Zwei Jahre Folgen, und ich konnte mir nie merken, ob wir etwas schon behandelt hatten — also haben wir uns entweder wiederholt oder gute Themen aus Angst vermieden. Jetzt ist es durchsuchbar und diese Sorge ist einfach weg. Die Kommentar-Triage bedeutet außerdem, dass meine Co-Hostin den Beleidigungsordner nicht mehr liest, was sie mehr belastet hat, als sie zugab.",name:"Podcast-Duo, Berlin"}]},{slug:"home-buyers",title:"KI für den Wohnungskauf: weniger Besichtigungen — KI-Coaching Berlin",metaDescription:"Neue Angebote erreichen Sie in Minuten, unpassende Wohnungen werden mit Begründung aussortiert, und jede Wohnung zeigt vor der Besichtigung ihre echten Kosten.",label:"Immobilienkauf",headline:"Es geht nicht darum, Ihnen mehr Wohnungen zu zeigen, sondern weniger.",story:["Ein Paar in Berlin, seit vierzehn Monaten auf der Suche. Eine Familie, die einen bestimmten Schuleinzugsbereich braucht. Ein Mann, der seiner Mutter eine Wohnung in einer anderen Stadt kauft. Zwei Menschen, die zum Sanieren kaufen. Alle sind auf dieselbe Art erschöpft, und alle haben angefangen, ihre Ansprüche zu senken, ohne es zu merken.","Samstag- und Sonntagvormittag auf den Portalen, immer dieselben vierzig Wohnungen. Die guten Angebote sind binnen Stunden weg. Wer am Wochenende sucht, sieht also nur, was sonst niemand wollte. Und jedes Angebot, das gefällt, braucht vierzig Minuten Prüfung — Exposé, Hausgeld, Energieausweis, Arbeitsweg, echte Erwerbskosten. Diese vierzig Minuten leisten sie vielleicht zweimal die Woche, schlecht, um Mitternacht."],machinery:["Jedes relevante Portal rund um die Uhr beobachten und ein neues Angebot binnen Minuten erfassen","Dubletten erkennen: dieselbe Wohnung bei drei Maklern zu drei Preisen","Ihre harten Kriterien anwenden — Zimmer, Fläche, Etage, Aufzug, Budget, Bezirk","Das Exposé lesen: Hausgeld, Wohnfläche, Baujahr, Heizung, Energieausweis, Erbpacht, Denkmalschutz, Sanierungsstau","Die echten Erwerbskosten rechnen — Grunderwerbsteuer, Notar und Grundbuch, Courtage — meist 10–12% über dem Angebotspreis","Tür-zu-Tür-Fahrzeiten zu echten Adressen zu echten Tageszeiten","Das Besichtigungsbriefing zusammenstellen und festhalten, warum jede Wohnung abgelehnt wurde"],judgement:["Ob Sie dort glücklich wären","Was es Ihnen wert ist","Wie viel Sie bieten und ob Sie überhaupt kaufen"],builds:[{name:"Der Wächter",text:"Läuft rund um die Uhr. Neue Angebote, die Ihre harten Kriterien erfüllen, kommen binnen Minuten per Nachricht — nicht am Samstag. Das allein verändert das Ergebnis mehr als alles andere zusammen, denn in Berlin bildet sich die Schlange in den ersten zwei Stunden."},{name:"Der Aussortierer",text:"Der Teil, den viele erst seltsam finden und dann nicht mehr missen wollen. Er wirft Angebote weg und sagt warum: „Erbpacht bis 2061 — haben Sie ausgeschlossen.“ „Hausgeld 610 € für 68 m² — über Ihrer Grenze.“ Der abgelehnte Stapel bleibt sichtbar, aber eingeklappt, damit Sie sehen: Hier wurde nichts leichtfertig weggeworfen."},{name:"Die Echtkosten-Zeile",text:"Jedes verbleibende Angebot trägt eine Zahl: was Sie nach dem Notartermin tatsächlich bezahlt haben, und die Monatsrate bei Ihrem angegebenen Eigenkapital. Den Zinssatz geben Sie ein — wir erfinden ihn nicht."},{name:"Das Besichtigungsbriefing",text:"Eine Seite pro Wohnung: die acht Dinge, auf die man in dieser Bauepoche achtet — Altbau um 1900, 60er, Plattenbau und Neubau haben je eigene Listen — die sechs Fragen an den Makler und die zwei Unterlagen, die Sie anfordern."},{name:"Das Ablehnungsprotokoll",text:"Nach elf Besichtigungen weiß niemand mehr, warum Nummer vier ausschied. Das Protokoll hält jeden Grund fest und verhindert so das langsame, unbemerkte Senken der Ansprüche."}],stops:{title:"Es sagt Ihnen nie, ob Sie kaufen sollen, und fasst kein Geld an.",text:["Keine Wertermittlung, kein „das ist unter Wert“, keine Finanzierungsempfehlung. Wir sind keine Finanzberater, und die Software ist es auch nicht. Sie rechnet, was sich rechnen lässt, und gibt die Entscheidung unangetastet an Sie zurück. Wirkt ein Angebot auffällig, sagt sie auffällig und schlägt vor, eine Fachperson zu fragen — sie zieht den Schluss nicht für Sie.","Sie kontaktiert auch keine Makler. Anfragen werden entworfen; Sie senden sie."]},proof:"Besichtigungen pro hundert gesehener Angebote — sollte deutlich steigen. Minuten von der Veröffentlichung bis zu Ihrer gesendeten Anfrage. Wochenendstunden auf den Portalen — sollten auf null gehen.",refuse:"Wenn Budget und Anforderungen nicht beide wahr sein können. Das System würde dann Woche für Woche schlicht Stille produzieren, und das ist eine grausame Art, es zu erfahren. Wir sagen es stattdessen in Woche eins, mit der Rechnung auf dem Tisch.",cost:"Eine Sitzung, in der Sie Ihre harten Kriterien festlegen — zu zweit, wenn Sie zu zweit kaufen, denn dort kommen die echten Meinungsverschiedenheiten auf den Tisch. Danach wöchentlich nichts. Die Angebote kommen zu Ihnen.",quotes:[{text:"Vierzehn Monate Samstage auf Portalen, immer dieselben vierzig Wohnungen, und langsam stimmten wir Dingen zu, von denen wir gesagt hatten, das nie. Die Kriteriensitzung dauerte zwei Stunden und war überwiegend ein Streit zwischen uns beiden — was, glaube ich, das eigentliche Produkt war. Danach haben wir gar keine Angebote mehr durchgesehen: Es kam binnen Minuten nach Veröffentlichung an, und was nicht passte, wurde weggeworfen, mit einer Begründung daneben. Wir haben neun Wohnungen gesehen statt vierzig und die siebte gekauft.",name:"Paar, Prenzlauer Berg"},{text:"Was ich brauchte, war die echte Zahl, nicht der Preis in der Überschrift. Es hat mir die Grunderwerbsteuer gezeigt, den Notar, das Hausgeld, alles — und zwei Wohnungen, auf die wir uns gefreut hatten, lagen außerhalb dessen, was wir tragen können. Er war sehr klar darin, dass er uns nicht sagt, ob wir kaufen sollen, und die Finanzierung nicht anfasst. Das fühlte sich damals wie eine Einschränkung an und später wie der Grund, warum ich dem Rest vertraut habe.",name:"Familie, Neukölln"}]},{slug:"lawyers",title:"KI für Anwälte: Verträge kommen markiert an — KI-Beratung Berlin",metaDescription:"Verträge bei Eingang abgelegt und versioniert, jede Frist im Kalender, und jeder Entwurf öffnet sich in Word mit begründeten Vorschlägen, die Sie einzeln prüfen.",label:"Anwälte",headline:"Der Vertrag ist schon markiert, wenn Sie ihn öffnen.",story:["Eine Wirtschaftskanzlei mit zwei Partnern. Eine Rechtsabteilung mit fünf Personen. Drei Einzelanwälte. Eine Syndika, die die gesamte Rechtsfunktion eines 300-Personen-Unternehmens ist. Im Recht sind sie nicht im Rückstand. Im Rückstand sind sie bei Verträgen als Dateien — die ankommen, wandern, sich ändern und verloren gehen.","Ein Vertrag kommt als Anhang namens Vertrag_final_final_v3(2).docx. Jemand antwortet mit Änderungsverfolgung aus einer Fassung, die längst überholt war. Drei Wochen später verstreicht unbemerkt eine Frist, die nur in diesem Dokument stand. Niemand kann sagen, welche Fassung unterschrieben wurde. Die Juristin verbringt den Abend mit Archivarbeit — mit zwei Staatsexamen."],machinery:["Verträge in dem Moment aus dem Postfach holen, in dem sie ankommen","Jede Datei nach einer festen Konvention benennen und versionieren, dauerhaft, mit erhaltener Historie","Die Eckdaten herausziehen: Parteien, Daten, Laufzeit, Kündigungsfristen, Rechtswahl, Haftungsgrenzen, Verlängerung","Der Fristenkalender — jedes Datum in jedem Vertrag, sichtbar bevor es zählt","Einen eingehenden Entwurf mit dem eigenen Playbook der Kanzlei vergleichen und Abweichungen markieren","Nachfassen bei der Gegenseite, die den Entwurf nicht zurückschickt, und beim internen Unterzeichner","Korrekt und beim ersten Mal in der Dokumentenablage der Kanzlei ablegen","„Wo ist dieser Vertrag, und welche Fassung gilt?“ sofort beantworten"],judgement:["Ob eine Klausel akzeptabel ist","Was zugestanden wird","Beratung","Unterschrift"],builds:[{name:"Das überwachte Postfach",text:"Jeder Anhang wird erkannt, versioniert, mit Akte und Vorgängerfassung verknüpft und abgelegt. Das final_final_v3(2)-Problem verschwindet in Woche eins, und das ist die Veränderung, die zuerst auffällt."},{name:"Das Vertragsdatenblatt",text:"Ein strukturierter Datensatz pro Vertrag. Jedes Feld trägt einen Verweis auf genau die Seite und den Absatz, aus dem es stammt. Nichts wird ohne Fundstelle behauptet, denn eine Angabe, die Sie nicht prüfen können, ist schlimmer als keine — sie sieht aus wie Wissen."},{name:"Der Playbook-Abgleich",text:"Die Positionen der Kanzlei, einmal richtig aufgeschrieben. Das ist die härteste und wertvollste Woche des Projekts, weil die meisten Kanzleien ihre nie aufgeschrieben haben. Danach wird jeder eingehende Entwurf dagegen markiert."},{name:"Die erste Durchsicht",text:"Das Herz des Systems. Ein Word-Dokument mit Änderungsverfolgung, in dem jeder einzelne Vorschlag seine Begründung als Kommentar trägt: aus welcher Playbook-Position er kommt oder welches Risiko er adressiert. Sie öffnen es in Word — Ihrem eigenen Werkzeug, nicht unserem — und nehmen jeden Vorschlag von Hand an oder verwerfen ihn."},{name:"Der Fristenkalender",text:"Jedes Datum landet in Ihrem Kalender, mit Erinnerungen, die näher am Termin eindringlicher werden. Das Stück mit dem höchsten Rohwert, denn eine versäumte Kündigungsfrist ist ein Haftungsfall."}],stops:{title:"Niemals juristische Bewertung, und nichts verlässt ungelesen das Haus.",text:["Keine Beratung, an niemanden, zu keinem Zeitpunkt, intern wie extern. Kein automatischer Versand an die Gegenseite. Keine Klausel wird ohne genannte Begründung umformuliert, die Sie bewerten können. Jede herausgezogene Angabe ist an ihre Fundstelle geheftet, sodass die Prüfung vier Sekunden dauert. Es gibt kein „Alle übernehmen“ — wir wurden gebeten, das zu bauen, und haben abgelehnt.","Dazu die Bedingungen, die es in Deutschland überhaupt einsetzbar machen: DSGVO-Konformität mit AV-Vertrag, Datenhaltung in der EU, kein Training auf Mandanteninhalten, gewahrtes Mandatsgeheimnis, ein lückenloses Protokoll jedes Schritts und eine dokumentierte Antwort auf die Kammerfrage „Wer hat das getan, und können Sie es zeigen?“ Ein juristisches KI-System ohne dieses Protokoll ist nicht einsatzfähig, egal was es sonst kann."]},proof:"Zeit vom Eingang bis abgelegt und benannt. „Wo ist dieser Vertrag“ in Sekunden beantwortet. Versäumte Fristen: null. Und das, was die Partner nennen — Abende, die nicht mehr für Versionsarchäologie draufgehen.",refuse:"Individuelle, hochwertige Einzelverhandlungen. Dort gibt es kein Playbook, weil es keine Wiederholung gibt, und eine erste Durchsicht bei einem wirklich neuartigen Deal ist Rauschen im Gewand der Hilfe.",cost:"Zwei Wochen Ihrer Zeit, um das Playbook mit uns aufzuschreiben — die Positionen, die Ihre Kanzlei tatsächlich vertritt, nicht die, die sie zu vertreten glaubt. Danach etwa elf statt vierzig Minuten pro Vertrag, verbracht mit dem Lesen von Vorschlägen statt mit der Suche nach Fassungen.",quotes:[{text:"Allein das Versionsproblem hat uns Abende gekostet — Vertrag_final_final_v3, und niemand konnte sagen, welcher unterschrieben wurde. Im ersten Monat hat er nur Eingang und Ablage ausgeliefert und dann aufgehört, was ich seltsam fand, bis ich verstand, dass es Absicht war. Die Durchsicht kam später, und jeder einzelne Vorschlag kommt in Word mit einer Begründung an, und ich nehme jeden selbst an oder verwerfe ihn. Er wurde um einen „Alle übernehmen“-Knopf gebeten und hat abgelehnt — hätte er ihn gebaut, hätte ich nicht weiter mit ihm gearbeitet.",name:"Partnerin, Wirtschaftskanzlei"},{text:"Wir sind fünf Menschen und machen die Rechtsarbeit eines Unternehmens mit dreihundert. Meine Woche verändert hat der Fristenkalender — jede Kündigungsfrist in jedem Vertrag ist jetzt ein Termin, von dem ich erfahre; vorher hatten wir einen verpasst, und das war teuer. Die Extraktion heftet jedes Feld an die Seite, von der es stammt, also dauert das Prüfen vier Sekunden statt Vertrauen zu erfordern. Das Audit-Log war für uns nicht verhandelbar, und es war das Erste, wonach er gefragt hat, nicht das Letzte.",name:"Syndika, Industrie, ~300 Beschäftigte"}]},{slug:"teachers",title:"KI für Lehrkräfte: Sonntage zurück, die Note bleibt Ihre — KI-Beratung Berlin",metaDescription:"Drei Niveaustufen aus einem Arbeitsblatt, eine Korrektur, die Belege findet und die Note Ihnen überlässt, Zeugnisbemerkungen aus Ihren Notizen. Keine Schülerdaten verlassen den Raum.",label:"Lehrkräfte",headline:"Das Werkzeug findet den Beleg. Sie geben die Note.",story:["Drei Gymnasiallehrkräfte, zwei aus der Grundschule, ein Berufsschullehrer und zwei Nachhilfelehrerinnen. Jede und jeder leistet etwa zwölf unbezahlte Stunden pro Woche, und fast keine davon ist Unterricht.","Sonntag. 28 Texte korrigieren, jeder braucht einen Kommentar, der mehr sagt als „gut“. Dann ein Arbeitsblatt auf drei Niveaus bringen. Dann Elternbriefe. Und zweimal im Jahr die Zeugnisse: 28 Bemerkungen zwischen 21 Uhr und Mitternacht, jede angeblich individuell, alle geschrieben, wenn man zu müde ist, individuell zu sein."],machinery:["Drei Schwierigkeitsstufen eines Arbeitsblatts aus einem Original erzeugen","Eine erste Korrektur nach Ihrer Rubrik: den Beleg für jedes Kriterium im Schülertext finden und zitieren","Ihre eigenen Kurznotizen in vollständige Zeugnissätze im Stil Ihrer Schule bringen","Elternmails aus Stichpunkten entwerfen, in passender Förmlichkeit","Übungsaufgaben, kurze Abfragen und Vokabeltrainings erstellen","Unterrichtsgerüste entlang des Rahmenlehrplans aufbauen","Verwaltung: Sitzpläne, Ausflugsbriefe, Einverständniserklärungen, Vertretungsnotizen","Zeigen, welche Aufgaben die ganze Klasse verfehlt hat und was das nahelegt"],judgement:["Die Note","Was mit einem bestimmten Kind los ist","Was man besorgten Eltern sagt","Was diese Klasse am Dienstag braucht"],builds:[{name:"Drei Niveaus aus einem Arbeitsblatt",text:"Ein Arbeitsblatt rein, drei raus: mit Hilfen, Standard, Erweiterung. Gleicher Inhalt, andere Unterstützung. Hier verschwinden die Differenzierungsstunden, und es ist reine Routine: Sie wissen längst, wie die Version mit Hilfen aussieht, Sie haben nur keine Zeit, sie dreimal zu tippen."},{name:"Die Korrekturhilfe",text:"Ihre Rubrik, einmal eingegeben. Jede Abgabe kommt mit den Belegen zu jedem Kriterium zurück, gefunden und zitiert, und ohne Note. Die Korrekturzeit halbiert sich etwa. Was Lehrkräfte nicht erwartet haben: Das Feedback wird konkreter, weil der Beleg schon zitiert ist und Sie aufhören, „guter Aufbau“ zu schreiben."},{name:"Die Zeugnishilfe",text:"Sie schreiben sechs Wörter über ein Kind. Zurück kommen drei Sätze im Stil Ihrer Schule, gebaut aus Ihren Notizen und sonst nichts. Sie überarbeiten jeden einzelnen. Über ein Kind wird nichts geschrieben, was Sie nicht zuerst selbst beobachtet haben."},{name:"Der Elternbrief-Entwurf",text:"Stichpunkte rein, passender Brief raus. Jeder wird von Ihnen gelesen und dann von Ihnen verschickt."},{name:"Die Klassenauswertung",text:"Welche Aufgaben die Klasse verfehlt hat und was die häufigste falsche Antwort über das Missverständnis dahinter verrät. Das ändert, was Sie am Dienstag unterrichten, und es ist der einzige Punkt auf dieser Liste, der den Unterricht selbst besser macht."}],stops:{title:"Das Werkzeug gibt nie eine Note, und keine Schülerdaten verlassen den Raum.",text:["Die Notengrenze ist pädagogisch und rechtlich zugleich: In deutschen Schulen gehört die Note der Lehrkraft, und in den meisten Ländern ist eine automatisierte Note schlicht nicht zulässig. Sie ist auch einfach richtig. Die Korrekturhilfe findet Belege, und Belege zu gewichten ist Unterrichten.","Die Datengrenze ist härter und nicht verhandelbar. Kinderdaten liegen nahe an der am stärksten geschützten Kategorie der DSGVO, Schulen haben eigene Datenschutzregeln, und die Länder unterscheiden sich darin, was überhaupt einen US-Dienst berühren darf. Also: Namen werden entfernt, bevor irgendetwas das Gerät verlässt, Verarbeitung auf Ihrem eigenen Rechner, wo immer das geht, keine Namen, keine Geburtsdaten, kein Förderbedarf, keine Familienverhältnisse. Wo die Regeln einer Schule externe Verarbeitung ganz verbieten, bauen wir die lokale Version oder gar nichts. Und über Charakter, Potenzial oder häusliche Lage eines Kindes wird nie etwas erzeugt."]},proof:"Sonntagsstunden. Korrekturminuten pro Klassensatz. Zeugniszeit in Abenden statt in Wochen. Und ob das Feedback, das Schülerinnen und Schüler bekommen, konkreter geworden ist. Das merken Lehrkräfte innerhalb eines Korrekturdurchgangs.",refuse:"Wenn die Schule das als Überwachungssystem will: Engagement-Werte, Verhaltensprognosen, Vergleichstabellen über Kinder. Das hat keine der acht Lehrkräfte gewollt. Danach fragt gelegentlich die Schulleitung im Nachhinein, und wir bauen es nicht.",cost:"Ein Nachmittag, um Ihre Rubrik einzugeben. Er rechnet sich mit dem ersten Klassensatz.",quotes:[{text:"Sonntag war Korrigieren und Differenzieren, und abends war für Montag nichts mehr übrig. Ein Arbeitsblatt wird jetzt in der Zeit zu drei Niveaus, die ich früher für das erste gebraucht habe. Der Korrekturdurchgang findet die Belege gegen meine eigene Rubrik und zitiert sie, und überlässt die Note mir — was das Gesetz ist und außerdem richtig. Das Unerwartete: Mein Feedback ist spezifischer geworden, weil der Beleg schon dasteht und ich aufgehört habe, achtundzwanzigmal „guter Aufbau“ zu schreiben.",name:"Gymnasiallehrerin, Deutsch und Geschichte"},{text:"Ich war skeptisch, weil bei allem, was man mir gezeigt hatte, Kinderdaten irgendwohin gingen, wo ich sie nicht sehen konnte. Er hat alles pseudonymisiert, bevor es meinen Laptop verlassen hat, und mir ein einseitiges Dokument gegeben, das ich meiner Schulleitung geben konnte — das war der Grund, warum ich es überhaupt nutzen durfte. Zeugnisbemerkungen haben zwei Wochen Abende gekostet und kosten jetzt zwei Nachmittage, und jede beginnt immer noch mit sechs Wörtern, die ich selbst über dieses Kind geschrieben habe.",name:"Grundschullehrerin, Berlin-Wedding"}]},{slug:"coaches",title:"KI für Coaches & Yogalehrende: weniger Verwaltung — KI-Beratung Berlin",metaDescription:"Neun Stunden Verwaltung pro Woche. Bei drei von fünf war die Lösung ein Buchungssystem, keine KI. Was sich lohnte: eine Sprachnotiz, die zur Sitzungsnotiz wird.",label:"Coaches & Yogalehrende",headline:"Bei drei von fünf lautete die ehrliche Antwort: ein Buchungssystem, keine KI.",story:["Zwei Yogalehrerinnen mit eigenem Studio, ein Personal Trainer, ein Business-Coach, eine Pilates-Lehrerin. Alle führen ein Ein-Personen-Unternehmen, in dem das Produkt Präsenz ist und der Aufwand Verwaltung. Es ist zugleich die Gruppe, der KI-Werkzeuge am hartnäckigsten verkauft werden, und die Gruppe, die am wenigsten davon braucht.","Die Verwaltung ist zersplittert, und genau deshalb ist sie schlimmer, als sie aussieht. Buchungsanfragen über WhatsApp, Instagram und E-Mail. Der No-Show, der gebucht hat und nie kam. Rechnungen zum Monatsende. Der Newsletter, der seit März nicht mehr rausging. Sitzungsnotizen, drei Tage später aus dem Gedächtnis geschrieben. Neun Stunden pro Woche, keine davon in Blöcken, die sich wie Arbeit anfühlen, alle in den Lücken, die eigentlich Erholung sein sollten."],machinery:["Buchung, Stornierung, Warteliste und Erinnerungen","Zahlung und Rechnung, inklusive Kleinunternehmerhinweis nach §19 UStG","Nachfassen bei No-Shows und bei Kundinnen, die länger nicht da waren","Kurs- und Workshopbeschreibungen aus ein paar Stichworten entwerfen","Eine durchsuchbare Bibliothek Ihrer Sequenzen und Übungen pflegen","Einen gesprochenen Zwei-Minuten-Rückblick in eine schriftliche Kundennotiz verwandeln","Den Newsletter aus dem Material des Monats zusammenstellen, und den Export für die Steuer"],judgement:["Was dieser Körper heute braucht","Die Beziehung, die das ganze Geschäft ist","Ob jemand gefordert oder gebremst werden sollte","Was am Donnerstag unterrichtet wird"],builds:[{name:"Zuerst die langweilige Grundausstattung",text:"Ein ordentliches Buchungssystem mit Erinnerungen und Kartenzahlung nahm etwa sechs der neun Stunden weg, und das haben wir in der ersten Woche gesagt. Keine KI darin. Der KI-Teil danach ist klein und konkret."},{name:"Die Sprachnotiz, die zur Sitzungsnotiz wird",text:"Sie sprechen neunzig Sekunden, nachdem die Kundin gegangen ist. Das Werkzeug macht daraus eine strukturierte Notiz — woran gearbeitet wurde, worauf zu achten ist, womit Sie nächstes Mal beginnen — und legt sie bei der Person ab. Es ist das Wertvollste, was wir für diese Gruppe gebaut haben, weil die Notiz dadurch überhaupt entsteht. Und genau dafür zahlen Ihre Kundinnen: dass Sie wissen, wo Sie beim letzten Mal aufgehört haben."},{name:"Die Sequenzbibliothek",text:"Jede Sequenz, die Sie je unterrichtet haben, durchsuchbar nach Schwerpunkt, Niveau, Dauer und Kontraindikation. Die Planung sinkt von vierzig Minuten auf acht, und Sie wiederholen nicht mehr unbemerkt dieselben sechs Stunden."},{name:"Der Beschreibungsentwurf",text:"Aus sechs Wörtern wird eine Workshopbeschreibung in Ihrer Sprache. Diese Sprache bauen wir aus zwanzig Ihrer eigenen früheren Beschreibungen, nicht aus einer Stilanweisung."},{name:"Die Reaktivierungsliste",text:"Wer seit sechs Wochen nicht gebucht hat, mit der letzten Notiz dazu, damit die Nachricht echt sein kann statt „Wir vermissen dich!“"}],stops:{title:"Keine Gesundheitsberatung, und keine Nachricht geht in Ihrem Namen raus, ohne dass Sie sie gelesen haben.",text:["Die Gesundheitsgrenze: keine Empfehlung zu Übungsvarianten, keine Deutung einer Verletzung, kein „geeignet in der Schwangerschaft“, keine Ernährung. Das ist Ihre Versicherung, Ihre Haftung, Ihr Urteil. Erwähnt eine Kundennotiz eine Erkrankung, speichert das System sie als Text und schlägt nichts vor.","Die Stimmgrenze zählt mehr, als man denkt. Ihre Kundinnen merken es. Eine erzeugte Nachricht, die danebengeht, kostet mehr als die zehn Minuten, die sie gespart hat, denn wofür Menschen hier zahlen, ist, dass jemand wirklich aufpasst. Wir entwerfen; Sie senden."]},proof:"Verwaltungsstunden pro Woche, ehrlich gezählt. Ihre No-Show-Quote — allein die Erinnerungen halbieren sie meist. Der Anteil der Sitzungen mit tatsächlich geschriebener Notiz, der bei etwa 30% beginnt und bei etwa 95% endet. Reaktivierte Kundinnen pro Quartal.",refuse:"Oft, in dieser Gruppe. Drei von fünf kamen mit dem Wunsch nach einem KI-Assistenten und brauchten einen Kalender mit automatischen Erinnerungen. Wir haben ihn eingerichtet, den Nachmittag berechnet und gesagt, dass sich der KI-Teil noch nicht rechnet. Zwei davon haben uns seither vier Menschen geschickt. Nein zu sagen ist unser Marketing.",cost:"Neunzig Sekunden Sprechen nach jeder Sitzung. Sonst nichts.",quotes:[{text:"Ich habe ihn um einen KI-Assistenten gebeten, und er hat mir gesagt, ich brauche ein Buchungssystem mit automatischen Erinnerungen, hat es an einem Nachmittag eingerichtet, mir den Nachmittag berechnet und gesagt, der KI-Teil rechne sich noch nicht. Das hat etwa sechs Stunden pro Woche weggenommen. Das Einzige, was er gebaut hat, ist die Sprachnotiz nach jeder Sitzung, neunzig Sekunden, aus der eine schriftliche Kundennotiz wird — ich komme jetzt zu einer Sitzung und weiß schon, wo wir aufgehört haben. Ich habe ihm seither vier Menschen geschickt.",name:"Inhaberin eines Yogastudios, Kreuzberg"},{text:"Das Planen hat vierzig Minuten gekostet, weil ich Sequenzen neu erfunden habe, die ich längst unterrichtet hatte. Alles, was ich je unterrichtet habe, ist jetzt nach Schwerpunkt, Niveau und Kontraindikation durchsuchbar, das Planen dauert acht Minuten, und ich unterrichte nicht mehr versehentlich dieselben sechs Stunden im Wechsel. Er wollte nichts bauen, das Gesundheitshinweise gibt oder Nachrichten als ich verschickt — und da meine Kundschaft das sofort merken würde, war das die richtige Linie.",name:"Personal Trainer, Berlin"}]},{slug:"product-managers",title:"KI für Produktmanager: alles Feedback gelesen — KI-Beratung Berlin",metaDescription:"Feedback aus allen Kanälen nach Themen gebündelt, die Originalzitate bleiben. Meetings werden zu Ticketentwürfen, Dubletten gefunden. Was gebaut wird, entscheiden Sie.",label:"Produktmanager",headline:"Es liest das ganze Feedback und schreibt die Tickets. Was gebaut wird, entscheiden Sie.",story:["Zwei PMs in einem mittelgroßen SaaS-Unternehmen, einer bei einem Marktplatz, eine, die als einzige PM in einem Startup mit 40 Leuten zusätzlich Support, Analytics und Release Notes macht. Diese Gruppe hat am ehesten schon drei KI-Werkzeuge selbst ausprobiert und alle drei wieder aufgegeben — weil die Werkzeuge das Schreiben automatisiert haben, und Schreiben war nie der Engpass.","Zwei Dinge brechen. Das erste ist Feedback: Es kommt in Zendesk an, in Slack, in Vertriebsgesprächen, in App-Store-Bewertungen, auf drei verschiedenen Notion-Seiten. Alles ordentlich zu lesen würde einen Tag pro Woche kosten, also tut es niemand. Das zweite ist die Statusarbeit: das Wochenupdate, die Release Notes, die Mail an die Stakeholder, das Ticket aus dem Meeting, das vor neun Minuten zu Ende ging."],machinery:["Feedback aus allen Quellen fortlaufend an einem Ort sammeln","Nach Themen bündeln und dieselbe Beschwerde in elf Formulierungen zusammenführen","Menge, Kundensegment und Umsatz an jedes Thema hängen","Meetingaufnahmen in Ticketentwürfe mit Akzeptanzkriterien verwandeln","Backlog-Einträge finden, die in achtzehn Monaten viermal angelegt wurden","Release Notes aus gemergten Pull Requests und geschlossenen Tickets entwerfen","Das wöchentliche Stakeholder-Update aus dem entwerfen, was sich tatsächlich bewegt hat","Changelogs, Preisseiten und Stellenanzeigen benannter Wettbewerber im Blick behalten"],judgement:["Was gebaut wird","Wozu — und wem gegenüber — Nein gesagt wird","Ob das lauteste Thema auch das wichtige ist","Die Strategie"],builds:[{name:"Der Feedback-Trichter",text:"Jede Quelle, ein Ziel, wöchentlich nach Themen gebündelt, mit Menge und Segment dazu. Das Entscheidende: Die Originalzitate bleiben unter jedem Thema stehen — Sie lesen fünf echte Sätze pro Thema, keine Zusammenfassung. Zusammenfassungen von Nutzerfeedback sind der Weg, auf dem PMs den Kontakt zu ihren Nutzern verlieren, und genau daran scheitert jedes Werkzeug in diesem Feld."},{name:"Vom Meeting zum Ticket",text:"Aufnahme rein, Ticketentwürfe raus — mit Problembeschreibung, Akzeptanzkriterien und offenen Fragen, die als offen markiert sind. Sie überarbeiten und legen ab. Spart etwa vier Stunden pro Woche, wenn Sie Discovery-Gespräche führen."},{name:"Der Dublettenfinder",text:"Läuft über das gesamte Backlog. Der erste Lauf ist unangenehm — bei einem PM fielen 340 Einträge auf etwa 90 zusammen — und es ist die günstigste Verbesserung, die es für die meisten Backlogs gibt."},{name:"Der Release-Notes-Entwurf",text:"Aus gemergten Pull Requests, in der Sprache des Produkts, ohne die interne Ausdrucksweise."},{name:"Die Wettbewerbsbeobachtung",text:"Eine wöchentliche Übersicht: was benannte Wettbewerber ausgeliefert, an den Preisen geändert oder neu ausgeschrieben haben. Stellenanzeigen sind das früheste Signal, und niemand liest sie, weil es lästig ist — genau die Art Arbeit, die ein Werkzeug Ihnen abnehmen sollte."}],stops:{title:"Kein RICE-Score, keine Wirkungsschätzung, keine sortierte Roadmap.",text:["Priorisieren ist der Job. Wer ein vom Werkzeug sortiertes Backlog übernimmt, hat den einzigen Teil der Rolle abgegeben, der keine Büroarbeit ist. Ganz praktisch: Das Werkzeug sieht die Zusage nicht, die einem Kunden in einem Raum gemacht wurde, in dem es nicht war — und auch nicht die strategische Wette, die ein kleines Thema in diesem Quartal zum wichtigsten macht.","Es verschickt auch nie das Stakeholder-Update. Das Werkzeug entwirft, Sie überarbeiten und senden. Statuskommunikation ist politisch, und das Werkzeug kann die Politik nicht lesen."]},proof:"Der Anteil des eingehenden Feedbacks, den tatsächlich ein Mensch liest — von etwa 15% auf nahezu alles. Stunden pro Woche für Status und Schreibarbeit. Größe des Backlogs, nachdem die Dubletten weg sind. Zeit vom Discovery-Gespräch bis zum abgelegten Ticket, die von Tagen auf denselben Nachmittag sinken sollte.",refuse:"Wenn das eigentliche Problem ist, dass im Unternehmen niemand entscheidet und die PM Daten will, um eine Entscheidung zu erzwingen. Mehr gebündeltes Feedback erzeugt keine Entscheidung. Es erzeugt eine besser belegte Pattsituation.",cost:"Jede Woche fünf Zitate pro Thema lesen. Was ohnehin der Job war.",quotes:[{text:"Ich hatte schon drei KI-Werkzeuge ausprobiert und alle drei aufgegeben, weil sie das Schreiben automatisiert haben und Schreiben nie mein Engpass war. Der Feedback-Trichter behält die Originalzitate unter jedem Cluster, also lese ich fünf echte Sätze pro Thema statt einer Zusammenfassung, und dieser Unterschied ist die ganze Sache. Der Dublettenlauf hat unser Backlog an einem Nachmittag von dreihundertvierzig auf etwa neunzig gebracht, was demütigend war. Es bewertet und sortiert nichts, und wenn es das täte, würde ich es nicht benutzen.",name:"Produktmanagerin, B2B-SaaS"},{text:"Ich bin die einzige PM in einem Unternehmen mit vierzig Leuten, also mache ich auch Support und Release Notes. Meetings werden jetzt am selben Nachmittag zu Tickets mit Akzeptanzkriterien statt drei Tage später, wenn ich die Feinheiten vergessen habe. Die Wettbewerbsbeobachtung liest deren Stellenanzeigen, was ich selbst nie täte, weil es langweilig ist — und es ist das früheste Signal, das es gibt. Ungefähr vier Stunden pro Woche zurück.",name:"Produktmanager, Marktplatz-Startup"}]},{slug:"online-shoppers",title:"KI beim Online-Kauf: Scheinrabatte erkennen — KI-Coaching Berlin",metaDescription:"Ein Preisverlauf, der Scheinrabatte entlarvt, Bewertungen gefiltert nach dem, was kaputtgeht, ein Rückgabekalender, ein Abo-Check. Meist ein Nachmittag, oft nicht viel.",label:"Online-Käufer",headline:"Der kleinste Auftrag auf dieser Liste, und der, den wir am häufigsten ablehnen.",story:["Zwei Menschen, die viel kaufen und den Überblick verlieren. Einer, der jeden Kauf wochenlang recherchiert und sich trotzdem übervorteilt fühlt. Ein kleiner Wiederverkäufer, der echte Preise kennen muss. Diese Gruppe hat auf der Liste am wenigsten zu gewinnen, und wir führen sie trotzdem auf, weil wir hier am häufigsten sagen: nicht viel.","Vor allem ist es Vergleichslähmung. Elf Browser-Tabs, vier Testportale, die alle über Provisionen leben, ein Preis, der gestern noch anders war, und der nagende Verdacht, dass der Rabatt keiner ist. Dazu das langsame Leck: Abos, die niemand gekündigt hat, Rücksendungen, die niemand rechtzeitig losgeschickt hat, Garantien, die niemand registriert hat."],machinery:["Den Preis eines Produkts über die Zeit und über Händler hinweg verfolgen und einen echten Rückgang melden","Den Scheinrabatt erkennen — den Preis, der zwei Wochen vor der Aktion gestiegen ist","Bewertungen nach denen filtern, die Haltbarkeit, Größe oder Defekte erwähnen","Die Rückgabefrist im Blick behalten und vor Ablauf erinnern","Wiederkehrende Abbuchungen mit dem Kontoauszug abgleichen","Garantien und Belege so ablegen, dass Sie sie wiederfinden","Eine Vergleichstabelle nach den Merkmalen bauen, die Ihnen wirklich wichtig sind"],judgement:["Ob Sie es kaufen","Ob es Ihnen das Geld wert ist","Geschmack"],builds:[{name:"Der Preiswächter",text:"Benannte Produkte, über die Zeit verfolgt, mit echtem Verlauf — so lässt sich „40% reduziert“ mit dem Märzpreis vergleichen. Eine Meldung bekommen Sie nur bei echten Tiefständen."},{name:"Der Bewertungsfilter",text:"Holt die Bewertungen, sortiert die offensichtlich bezahlten aus und hebt die hervor, die sagen, was wann kaputtgeht. Wie lange etwas hält, ist das, was Menschen eigentlich wissen wollen — und es liegt unter Fünf-Sterne-Bewertungen vom zweiten Tag begraben."},{name:"Der Rückgabe- und Garantiekalender",text:"Jeder Kauf bekommt ein Fristdatum und eine Belegdatei. Langweilig — und im Stillen das, was am meisten Geld spart."},{name:"Der Abo-Check",text:"Einmal zu Beginn: jede wiederkehrende Abbuchung mit Datum und Betrag aufgelistet. In allen vier Fällen kam dabei etwas Vergessenes zum Vorschein. Es ist eine Tabelle und ein Nachmittag."},{name:"Die Vergleichstabelle",text:"Für eine konkrete Entscheidung, nach Ihren Kriterien, mit den Quellen dazu."}],stops:{title:"Es kauft nichts, und es empfiehlt nichts.",text:["Keine hinterlegte Karte, kein automatischer Kauf, keine „Empfehlung der Redaktion“. Zum einen, weil ein Fehlkauf, den ein Werkzeug allein auslöst, echtes Geld kostet. Zum anderen, weil ein Empfehlungswerkzeug, das wir für eine einzelne Person bauen, eine schlechtere Version dessen ist, was Sie in zehn Minuten mit den gefilterten Daten vor sich selbst hinbekommen.","Es legt auch kein Profil von Ihnen an. Kein Verfolgen Ihres Verhaltens über Seiten hinweg, kein „Das könnte Ihnen auch gefallen“. Davon gibt es schon genug."]},proof:"Zurückgeholtes Geld aus gekündigten Abos und rechtzeitigen Rücksendungen — in allen vier Fällen lag das binnen eines Monats über unserem Honorar. Stunden pro Kaufentscheidung. Ob Sie sich noch übervorteilt fühlen, denn das ist die eigentliche Beschwerde darunter.",refuse:"Oft, und in dieser Gruppe am häufigsten. Drei Menschen haben uns um eine „Shopping-KI“ gebeten; zweien haben wir gesagt, sie würden mehr sparen, wenn sie aufschreiben, was sie in diesem Monat kaufen wollen. Das zwanghafte Recherchieren ist kein Werkzeugproblem — mehr Information macht es schlimmer, weil die Recherche eine emotionale Aufgabe erfüllt.",cost:"Ein Nachmittag, einmal. Danach kein laufender Aufwand, und das ist Absicht.",quotes:[{text:"Er hat mir das meiste von dem ausgeredet, worum ich gebeten hatte, was ich von jemandem, der eine Dienstleistung verkauft, nicht erwartet hätte. Das Abo-Audit hat eine Stunde gedauert und drei Dinge gefunden, für die ich seit 2022 zahle. Der Rückgabekalender ist langweilig und hat mir mehr gespart als alles Clevere. Er hat mir klar gesagt, dass eine Shopping-KI meine Recherchegewohnheit verschlimmern würde statt sie zu bessern, und auch damit hatte er recht.",name:"Privatkunde, Berlin"},{text:"Ich kaufe zum Wiederverkauf, also muss ich wissen, was Dinge über die Zeit wirklich kosten, nicht was heute auf einem Banner steht. Der Preisverlauf ließ mich eine „vierzig Prozent reduziert“-Aussage gegen den Märzpreis prüfen — es waren keine vierzig Prozent. Der Bewertungsfilter holt die Leute nach oben, die sagen, was wann kaputtging, und nur das interessiert mich. Ein Nachmittag Einrichtung, kein laufender Aufwand, worauf er ziemlich bestanden hat.",name:"Kleiner Wiederverkäufer"}]},{slug:"architects",title:"KI für Architekten: Protokolle am selben Abend — KI-Beratung Berlin",metaDescription:"Ein Planregister, das den aktuellen Stand kennt, sieben Angebote in einem Vergleich mit markierten Lücken, Baustellenprotokolle am selben Abend. Es entwirft nicht.",label:"Architekten",headline:"Der Papierkram ist am selben Tag erledigt. Entwurf und Konformitätsurteil bleiben bei Ihnen.",story:["Ein Zwei-Personen-Architekturbüro für Wohnungsumbauten, ein Einzelarchitekt vor allem für Bauanträge und Umbauten, und ein mittelgroßes Büro, in dem ein Partner die gesamte Ausschreibung und Vergabe verantwortet. Alle drei haben jahrelang gelernt zu entwerfen, und alle drei verbringen den Großteil ihrer Woche mit dem Papierkram rund um den Entwurf.","Für den einen ist es das Planregister: Welche Revision ging an wen, und hat der Statiker die aktuelle Fassung? Für den nächsten der Angebotsvergleich: sieben Angebote in sieben Formaten, Position für Position über ein Wochenende in Excel. Für den dritten das Baustellenprotokoll: vierzig Fotos, eine Stunde Notizen, und ein Dokument, das noch am selben Abend geschrieben werden muss, sonst wird es gar nicht geschrieben."],machinery:["Das Planregister: Welche Revision ging wann an wen, und welche gilt aktuell","Eine Einreichung gegen die Vollständigkeitsliste der Behörde prüfen","Angebote in eine vergleichbare Tabelle bringen, Position für Position","Baustellenfotos und diktierte Notizen in ein strukturiertes, datiertes Protokoll verwandeln","Offene Punkte aus Protokollen ziehen und bei den Verantwortlichen nachhalten","Die einschlägige Stelle in DIN, LBO, GEG oder Bebauungsplan finden","Das Gerüst des Leistungsverzeichnisses aus dem Entwurf vorbereiten","Einwendungs-, Nachtrags- und Gewährleistungsfristen im Blick behalten"],judgement:["Der Entwurf","Ob eine Lösung baubar und gut ist","Ob ein Angebot glaubwürdig ist, nicht bloß das günstigste","Ob etwas konform ist"],builds:[{name:"Das Planregister",text:"Jeder Plan, jede Revision, wer wann was bekommen hat. Klein und unspektakulär, und es nimmt eine wiederkehrende Sorge weg: „Hat der Statiker Rev C?“ wird zu einer Zwei-Sekunden-Frage mit einer Antwort, die Sie belegen können."},{name:"Der Angebotsvergleich",text:"Sieben PDFs rein, ein Vergleich raus, Position für Position. Nicht bepreiste Positionen werden als Lücke markiert, nicht als Null gezählt. Genau das ist die Falle im Angebotsvergleich: Das billigste Angebot ist sehr oft das, in dem etwas fehlt. Das Werkzeug markiert. Es entscheidet nicht."},{name:"Das Baustellenprotokoll am selben Abend",text:"Auf der Baustelle fotografieren und sprechen Sie. Am Abend liegt das Protokoll vor: datiert, mit Fotobezug, Mängel aufgelistet, Verantwortlichkeiten zugewiesen, Fristen in eine Nachhalteliste übernommen. Das Dokument, das früher um 22 Uhr oder gar nicht entstand, braucht jetzt fünfzehn Minuten Überarbeitung."},{name:"Der Normfinder",text:"Durchsucht Ihre eigene Normenbibliothek und den Bebauungsplan und liefert die Stelle mit Fundstelle. Er schlägt nach. Er gibt eine Norm nie in eigenen Worten wieder, denn eine umformulierte Norm ist ein Haftungsrisiko."},{name:"Die Vollständigkeitsprüfung",text:"Vor der Einreichung, gegen die Liste der Behörde. Sie fängt den fehlenden Nachweis ab, bevor das Bauamt es tut. Das spart Wochen."}],stops:{title:"Keine erzeugten Pläne, und nie der Satz „Das ist konform“.",text:["Keine Massenstudien, keine Grundrissvorschläge. Nicht weil Software nichts Planähnliches erzeugen könnte, sondern weil der Stempel des Architekten Haftung trägt und der Entwurf der gesamte Wert des Büros ist. Ein von Software erzeugter und von einem Menschen unterschriebener Entwurf ist das Schlechteste aus beidem.","Bei der Konformität findet das System die Norm und urteilt nie. Der Satz, den es sagen darf, lautet: „§34 BauGB, Absatz 2, könnte hier greifen — prüfen.“ Der Satz, den es nie sagen darf, lautet: „Das ist konform.“"]},proof:"Protokolle am selben Tag geschrieben: nahe 100%. Stunden pro Angebotsvergleich: Aus einem Wochenende werden etwa zwei Stunden. Wegen Unvollständigkeit zurückgewiesene Einreichungen: null. Zeit, bis „Welche Revision gilt?“ beantwortet ist.",refuse:"Wenn ein Büro generative Entwurfswerkzeuge will. Das ist ein anderer Beruf als unserer, und für ein Drei-Personen-Büro mit Umbauten löst es ein Problem, das es nicht hat, und bringt eine Haftung mit, die es nicht tragen kann.",cost:"Auf der Baustelle sprechen statt nachts schreiben. Sie fotografieren und diktieren vor Ort, und am Abend überarbeiten Sie das Protokoll fünfzehn Minuten lang, statt es zwei Stunden lang zu schreiben.",quotes:[{text:"Das Protokoll wurde früher um zehn Uhr abends geschrieben oder gar nicht, und „gar nicht“ lag vorn. Ich fotografiere und spreche jetzt vor Ort, und am selben Abend existiert das Dokument, mit Fotobezügen und herausgezogenen Fristen. Fünfzehn Minuten Überarbeiten statt zwei Stunden Schreiben. Er hat unsere Ordnerstruktur übernommen, statt seine eigene aufzudrängen — das klingt klein und hat dazu geführt, dass wir es tatsächlich weiter benutzen.",name:"Architekt, Einzelbüro"},{text:"Der Angebotsvergleich war ein Wochenende. Sieben Angebote in sieben Formaten, von Hand in Excel, und ich hatte immer Angst, etwas zu übersehen. Es normalisiert sie nach Position und markiert nicht bepreiste Positionen als Lücke statt als Null — das ist die eigentliche Falle, denn das billigste Angebot ist meist das, das etwas ausgelassen hat. Es markiert und schließt nicht. Jetzt zwei Stunden, und das Urteil ist weiter meines.",name:"Partner, Architekturbüro, ~14 Beschäftigte"}]},{slug:"project-managers",title:"KI für Projektleiter: kein Punkt geht verloren — KI-Beratung Berlin",metaDescription:"Meetings werden zu Aufgaben mit Namen und Datum, Erinnerungen in Ihren Worten, ein Statusbericht aus dem, was sich verändert hat. Die Ampel setzt das Werkzeug nie.",label:"Projektleiter",headline:"Das System listet auf, was gerutscht ist. Ob das Projekt Rot, Gelb oder Grün steht, entscheiden Sie.",story:["Einer im Bau, eine im IT-Rollout, einer in einem internen Transformationsprogramm. Alle drei beschreiben ihre Arbeit gleich, wenn man nachfragt: „Ich telefoniere Leuten hinterher und schreibe dann auf, dass ich hinterhertelefoniert habe.“","Vor allem freitagnachmittags. Der Statusbericht, von Hand aus vier Systemen und sechs Gesprächen zusammengesetzt, für ein Publikum, das nur auf die Ampelfarbe schaut und sonst nichts liest. Dazu die tägliche Variante: Meetings erzeugen Aufgaben, Aufgaben stehen im Protokoll, das Protokoll liest niemand nach, also erledigt niemand die Aufgaben. Aufgefallen ist es drei Wochen später, im schlechtesten Moment."],machinery:["Meetingaufnahmen oder Notizen in eine Aufgabenliste mit Verantwortlichem und Datum verwandeln","Diese Verantwortlichen rechtzeitig vor ihrem Termin erinnern","Erkennen, was sich seit dem letzten Bericht bewegt hat, statt das ganze Projekt neu zu beschreiben","Den Statusbericht aus Plan, Aufgabenliste und Risikoliste zusammensetzen","Die Risiko- und Problemliste aktuell halten und Risiken zeigen, deren Prüfdatum verstrichen ist","Abhängigkeiten beobachten: Wenn A rutscht, alles auflisten, was von A abhängt","Dieselbe Woche für drei Zielgruppen aufschreiben, ohne für eine davon etwas zu erfinden"],judgement:["Ob das Projekt wirklich rot ist","Was wann eskaliert wird","Welches Risiko echt ist","Wer was in welcher Reihenfolge erfahren muss"],builds:[{name:"Vom Meeting zur Aufgabenliste",text:"Aufnahme oder Notizen rein, Aufgabenliste raus: Verantwortlicher, Frist, Abhängigkeit, offene Frage, abgelegt in Ihrer Aufgabenverwaltung. Das schließt das größte Leck im Projektmanagement: Aufgaben, die im Raum beschlossen und auf dem Weg ins System verloren werden."},{name:"Die Erinnerung",text:"Verantwortliche bekommen vor ihrem Termin eine Nachricht, nicht danach. Sie ist in Ihren eigenen Worten vorformuliert und wird von Ihnen verschickt, damit weiterhin ein Mensch einen Menschen fragt. Alle drei nannten das Nachfassen den zermürbendsten Teil der Woche, gerade weil es sich wiederholt und immer ein wenig unangenehm ist."},{name:"Der Was-hat-sich-geändert-Bericht",text:"Der Statusbericht ist keine Zusammenfassung des Projekts, sondern eine Zusammenfassung dessen, was sich verändert hat. Software erkennt Veränderungen gut, Menschen schlecht. Er listet auf: verschobene Aufgaben, gerutschte Termine, neue oder geschlossene Risiken, überfällige Punkte. Sie schreiben die zwei Sätze, die sagen, was das bedeutet."},{name:"Die Folgenliste",text:"Wenn etwas rutscht, bekommen Sie sofort eine Liste von allem, was davon abhängt. Von Hand dauert das in einem großen Plan eine Stunde, und deshalb passiert es nicht in dem Moment, in dem es zählt."},{name:"Die drei Zielgruppen",text:"Eine Faktenbasis, drei Fassungen: Lenkungsausschuss, Team, Kunde. Überall dieselben Fakten. Für keine der drei wird etwas erfunden."}],stops:{title:"Es setzt nicht die Ampel und entscheidet nicht, was eskaliert wird.",text:["Die Farbe auf einem Statusbericht ist eine politische und fachliche Entscheidung. Ein Werkzeug, das sie setzt, wird entweder zum Stempel, den Sie ständig überschreiben, dann ist es nur Rauschen, oder zu etwas, dem Sie folgen, und das ist schlimmer.","Es schickt auch nie etwas nach oben. Berichte an Lenkungsausschuss oder Kunde werden vom Werkzeug vorbereitet und gehen immer mit Ihrer Unterschrift raus."]},proof:"Aufgaben aus Meetings, die in der Aufgabenliste landen: von etwa 60% auf nahezu alle. Stunden für den Wochenbericht: typischerweise von vier auf unter eine. Überfällige Aufgaben, die niemand bemerkt. Zeit von einem Verzug bis zum Wissen, was davon abhängt.",refuse:"Wenn ein Programm aus Gründen scheitert, an die kein Berichtswesen herankommt: kein Mandat, keine Mittel, ein Sponsor, der nicht entscheidet. Besseres Berichtswesen dokumentiert dort das Scheitern nur deutlicher. Gelegentlich will jemand genau das, aber dann bitte bewusst.",cost:"Meetings aufzeichnen, an denen Sie ohnehin teilnehmen, die Erinnerungen selbst verschicken, und zwei Sätze Einordnung pro Woche schreiben.",quotes:[{text:"Meine Stellenbeschreibung hätte lauten können: „Ich telefoniere Menschen hinterher und schreibe dann auf, dass ich hinterhertelefoniert habe.“ Aufgaben aus Meetings landen jetzt im Tracker, statt im Protokoll zu sterben — das war mein größtes Leck. Der Statusbericht wird aus dem gebaut, was sich verändert hat, statt aus dem ganzen Plan, also brauche ich unter einer Stunde und verbringe diese Stunde mit den zwei Sätzen, die sagen, was es bedeutet. Es setzt die Ampelfarbe nicht, und das soll es auch nicht.",name:"Projektmanagerin, IT-Rollout"},{text:"Die Abhängigkeitsspur würde ich behalten, wenn ich nur eines behalten dürfte. Wenn etwas rutscht, bekomme ich sofort die nachgelagerte Liste — von Hand dauerte das eine Stunde, also passierte es nie in dem Moment, in dem es zählte. Drei Publika aus einer sachlichen Grundlage haben mich außerdem davon abgehalten, freitagnachmittags dieselbe Woche dreimal zu schreiben. Nichts geht an den Lenkungsausschuss, ohne dass ich es sende — das war meine Bedingung und stellte sich als seine heraus.",name:"Bauleiter / Projektsteuerung, Infrastruktur"}]},{slug:"surveyors",title:"KI für Gutachter: Gutachten in 3 statt 8 Stunden — KI-Beratung Berlin",metaDescription:"Nummerierte Fotos vom Ortstermin mit Ihrer Sprachnotiz, Mängel in Ihren eigenen erprobten Formulierungen, exakte Normzitate, unverändertes Rohmaterial. Es bewertet nie.",label:"Gutachter",headline:"Aus acht Stunden Schreibarbeit werden drei. Die Bewertung bleibt bei Ihnen.",story:["Ein Bausachverständiger für Bauschäden und Beweissicherung, einer mit Schwerpunkt Verkehrswertgutachten, und einer, der vor allem Wohnungsübergaben und kleine Mängelberichte macht. Alle drei haften persönlich für jeden Satz, den sie unterschreiben, und diese eine Tatsache bestimmt, was wir überhaupt bauen dürfen.","Der Ortstermin dauert drei Stunden, das Schreiben acht. Fotos müssen nummeriert, platziert und verwiesen werden. Mängel müssen in der Standardformulierung beschrieben sein. Normen müssen exakt zitiert werden. Die Struktur muss jedes Mal dieselbe sein, weil ein Gericht das erwartet. Und jede Zeile muss im Kreuzverhör standhalten, also wird langsam geschrieben, nachts, und zweimal."],machinery:["Fotos vor Ort erfassen, mit Nummer, Ort, Uhrzeit und Ihrer Sprachnotiz automatisch dran","Diktierte Beobachtungen in strukturierte Mangeleinträge mit Fotobezug verwandeln","Ihre Bibliothek erprobter Standardformulierungen in Ordnung halten","Das Gutachten in Ihre feste Struktur setzen, Fotos platziert und verwiesen","Den einschlägigen Normtext mit exakter Fundstelle nachschlagen","Für Wertermittlungen: Vergleichswerte und Bodenrichtwert sammeln und die Rechenschritte der gewählten Methode ausführen","Fristen, Termine und Aktenzeichen führen, und die Kurzfassung aus dem Langgutachten erstellen"],judgement:["Die Ursache des Mangels","Die Bewertung. Der Wert. Die Schlussfolgerung","Was vor Gericht haltbar ist"],builds:[{name:"Die Ortstermin-App",text:"Fotografieren, sprechen, weitergehen. Jedes Foto trägt Nummer, Raum, Uhrzeit und Sprachnotiz. Der Ortstermin hinterlässt keinen Haufen unbeschrifteter Bilder mehr, der zwei Tage später aus dem Gedächtnis rekonstruiert werden muss. Genau dort gehen die meisten der acht Stunden verloren, und dort entstehen die meisten Fehler."},{name:"Die Mangeleinträge",text:"Diktierte Notizen werden zu strukturierten Einträgen in Ihrem eigenen Standardwortlaut, aus Ihrer eigenen Bibliothek, mit bereits korrekt zugeordneten Fotobezügen. Sie lesen und korrigieren jeden einzelnen."},{name:"Die Formulierungsbibliothek",text:"Ihre erprobten Wortlaute, nach Mangelart sortiert. Keine erzeugte Sprache, sondern Ihre Sprache, die der Prüfung schon standgehalten hat. Diese Unterscheidung macht das Ganze überhaupt erst vertretbar: Das Werkzeug holt bewährten Text hervor, es schreibt keinen neuen."},{name:"Das Normzitat",text:"Der exakte Text mit Fundstelle. Nie eine Umschreibung, denn eine umformulierte Norm im Gutachten ist ein Geschenk an die Gegenseite."},{name:"Die Vergleichswertsammlung",text:"Für Wertermittlungen: Vergleichswerte zusammengetragen, mit Quelle und Datum, die Rechnung Schritt für Schritt offengelegt. Die Wahl der Methode und die Anpassungen bleiben Ihre."}],stops:{title:"Roh bleibt roh, und das Urteil ist immer Ihres.",text:["Das ist die härteste Grenze in dieser ganzen Arbeit und die am wenigsten verhandelbare, denn Sie unterschreiben und Sie haften, im Zweifel vor Gericht, persönlich. Schadensursache: wird nie vorgeschlagen. Das System hält die Beobachtung fest und hört auf. Wert: wird nie erzeugt. Es sammelt die Eingaben und führt die Rechenschritte aus, die Sie vorgegeben haben. Schwere oder Einstufung: werden nie vergeben. Jeder Satz im fertigen Gutachten wurde entweder von Ihnen geschrieben oder wortgleich aus Ihrer eigenen freigegebenen Bibliothek übernommen und dann von Ihnen bestätigt.","Eine weitere Regel überrascht viele: Das System hält fest, was wann erfasst wurde, und das Rohmaterial bleibt unverändert. Wird ein Gutachten angegriffen, müssen Sie das Originalfoto, den Originalzeitstempel und die Originalsprachnotiz vorlegen können. Digital verbesserte Fotos, geglättete Notizen und rekonstruierte Zeitstempel wären allesamt katastrophal."]},proof:"Stunden pro Gutachten: von acht auf etwa drei, und diese drei gehen jetzt in die Bewertung statt ins Layout. Tage vom Ortstermin bis zum gelieferten Gutachten. Fehler im Fotoverweis: null. Gutachten pro Monat bei unveränderter Qualität.",refuse:"Jede Anfrage, den Bewertungsteil vorzuformulieren, wie vorsichtig auch immer verpackt. Ebenso jede Anfrage, mit den Formulierungen eines anderen Gutachters zu arbeiten. Die Bibliothek muss Ihre eigene sein, sonst trägt der Wortlaut keine Autorität, wenn er geprüft wird.",cost:"Vor Ort sprechen statt nachts schreiben, und jeden Eintrag lesen und bestätigen, bevor er ins Gutachten kommt.",quotes:[{text:"Acht Stunden Schreiben für drei Stunden Ortsarbeit, und das meiste der acht waren Fotos, Nummerierung und Querverweise. Ich fotografiere und spreche jetzt vor Ort, und jedes Bild trägt seine Nummer, seinen Raum und meine Notiz. Der Bericht setzt sich in unsere feste Struktur zusammen, und ich verbringe meine Zeit mit der Bewertung, dem einzigen Teil, der wirklich meiner ist. Er hat das System unter keiner Formulierung eine Schadensursache vorschlagen lassen — und da ich unterschreibe und persönlich hafte, war das die Antwort, die ich hören musste.",name:"Bausachverständiger"},{text:"Die Regel, die mich überzeugt hat, war, dass das Rohmaterial unangetastet bleibt. Originalfoto, Originalzeitstempel, Originalsprachnotiz, alles erhalten — denn wenn ein Gutachten angegriffen wird, muss ich sie vorlegen können. Die Formulierungsbibliothek ist mein eigener Wortlaut, aus meinen eigenen früheren Gutachten gezogen, keine von einer Maschine erfundene Sprache; diese Unterscheidung ist der ganze Grund, warum das in meinem Feld nutzbar ist. Drei Stunden pro Gutachten statt acht.",name:"Sachverständige für Verkehrswertermittlung"}]},{slug:"event-organizers",title:"KI für Veranstalter: ein Plan, weniger Nachfassen — KI-Beratung Berlin",metaDescription:"Ein Datensatz pro Veranstaltung, aus dem Ablaufplan, Briefings und Budget entstehen. Dienstleister werden rechtzeitig erinnert. Gebucht wird nur mit Ihrem Klick.",label:"Veranstalter",headline:"Nichts wird automatisch gebucht oder zugesagt.",story:["Eine Frau, die Firmenkonferenzen organisiert, ein Zwei-Personen-Team für Hochzeiten und jemand, der ein wiederkehrendes Stadtteilfest mit 400 Gästen auf die Beine stellt. Ihre Arbeit besteht zu 80% aus Nachfassen und zu 20% aus Geschmack — und das Nachfassen erstickt den Geschmack.","Vor allem das Nachfassen bei Dienstleistern. Vierzehn Gewerke, jedes in einem anderen Stand — angefragt, gebucht, Anzahlung geleistet, Endzahlen offen, Unverträglichkeiten ausstehend — geführt in einer Tabelle, die nicht aktuell ist, dazu Postfach und WhatsApp. Jeder Tag beginnt damit, herauszufinden, wer was schuldet. Dann der Ablaufplan, für jede Veranstaltung neu gebaut, und die Nachbereitung, die nie rausgeht, weil die Organisatorin dann längst schläft."],machinery:["Eine Übersicht pro Veranstaltung: jeder Dienstleister, sein Stand, Termin und Betrag","Erinnerungen an Dienstleister, die nicht geantwortet haben — planmäßig","Angebote so nebeneinandergelegt, dass man sie wirklich vergleichen kann","Der Ablaufplan, dazu eine Kurzfassung je Rolle — Catering, Technik, Kunde","Zu- und Absagen, Unverträglichkeiten und Barrierefreiheit, Sitzordnung und Namensschilder","Briefingunterlagen je Dienstleister, aus dem Gesamtplan abgeleitet","Budget gegen die Angebote verfolgt, Abweichungen markiert","Nach der Veranstaltung: Dankschreiben, Feedbackanfragen und der fertige Feedbackbericht"],judgement:["Ob der Raum sich richtig anfühlen wird","Welchem Dienstleister man vertraut — nicht welcher am günstigsten ist","Was gestrichen wird, wenn das Budget sich bewegt","Die Kundenbeziehung"],builds:[{name:"Ein Datensatz pro Veranstaltung",text:"Ein Datensatz pro Veranstaltung, aus dem alles andere entsteht: jeder Dienstleister, Kontakt, Stand, Termin, Betrag und jedes Dokument. Ablaufplan, Briefings und Budget werden daraus erzeugt, also wird nie etwas an zwei Stellen gepflegt — genau daran stirbt sonst jede Veranstaltungstabelle irgendwann."},{name:"Erinnerungen an Dienstleister",text:"Offene Punkte werden nachgefasst, bevor sie dringend werden. Die Erinnerung wird in Ihrem Ton vorformuliert, gesendet wird sie von Ihnen. Das Nachfassen bei Dienstleistern ist der größte Zeitfresser und der eintönigste Teil der Arbeit."},{name:"Ablaufplan und Rollenblätter",text:"Ein Gesamtzeitplan, dann ein kurzer Auszug je Rolle. Das Catering bekommt die vier Zeilen, die es betreffen, nicht sechzehn Seiten. Weniger Rückfragen am Tag selbst sind der eigentliche Gewinn — jede Rückfrage kostet Sie Aufmerksamkeit in dem Moment, in dem Sie am wenigsten davon haben."},{name:"Gästerückmeldungen",text:"Zu- und Absagen, Unverträglichkeiten und Barrierefreiheitsbedarfe werden automatisch gesammelt und in die Formate von Catering und Location gebracht."},{name:"Das Nachbereitungspaket",text:"Dankschreiben vorformuliert, Feedback angefragt, Ergebnisse zu einem Bericht zusammengestellt, den der Kunde tatsächlich bekommt. Zwei von dreien hatten das aus reiner Erschöpfung nie verschickt — und genau daher kommen Folgeaufträge."}],stops:{title:"Alles, was eine Verpflichtung erzeugt, ist Ihr Klick.",text:["Keine automatische Bestätigung, keine automatische Zahlung, keine automatische Annahme eines Angebots. Eine Veranstaltung hat ein festes Datum und Zusagen, die sich nicht zurücknehmen lassen — eine falsch bestätigte Buchung macht keine Entschuldigung ungeschehen.","Die Wahl des Dienstleisters ist eine Entscheidung, kein Vergleich. Das Werkzeug legt die Angebote nebeneinander und markiert, was in jedem fehlt. Eine Rangfolge erstellt es nie, denn Sie entscheiden nach Verlässlichkeit und Vorgeschichte — und beides steht in keinem Angebot. Gästedaten bleiben auf das Nötigste beschränkt und werden nach der Veranstaltung gelöscht: Unverträglichkeiten und Barrierefreiheitsbedarfe sind Gesundheitsdaten nach DSGVO, und keine Veranstaltung muss sie aufbewahren."]},proof:"Verwaltungsstunden pro Veranstaltung. Eine Woche vorher noch unbestätigte Dienstleister — sollten null sein. Rückfragen von Dienstleistern am Tag selbst. Ob das Nachbereitungspaket überhaupt rausgeht. Und irgendwann: Folgeaufträge.",refuse:"Bei ein bis zwei Veranstaltungen im Jahr rechnet sich das nicht. Ein Datensatz pro Veranstaltung lohnt sich ab etwa sechs Veranstaltungen jährlich; darunter sind eine gute Vorlage und ein gemeinsamer Kalender die ehrliche Antwort.",cost:"Einen Datensatz aktuell halten — statt vier Dinge aktuell zu halten.",quotes:[{text:"Jeder Morgen begann damit, aus einer Tabelle, einem Postfach und WhatsApp zu rekonstruieren, wer mir was schuldet. Es gibt jetzt einen Datensatz pro Veranstaltung, und Ablaufplan, Briefings und Budget sind Sichten darauf, also wird nie etwas zweimal gepflegt. Das Catering bekommt seine vier Zeilen statt sechzehn Seiten, und die Rückfragen am Tag selbst sind spürbar weniger geworden — was zählt, weil ich dann am wenigsten Aufmerksamkeit übrig habe. Ohne meinen Klick wird nichts gebucht oder bestätigt.",name:"Organisatorin, Firmenveranstaltungen"},{text:"Wir hatten aus reiner Erschöpfung nie ein Nachbereitungspaket verschickt, und es stellt sich heraus, dass genau daher die Folgeaufträge kommen. Dankschreiben entworfen, Feedback gesammelt, ein Bericht, den der Kunde tatsächlich bekommt. Er hat außerdem darauf bestanden, dass Unverträglichkeiten und Barrierefreiheitsbedarfe nach der Veranstaltung gelöscht werden — dass das Gesundheitsdaten sind, hatte ich nie bedacht und kann es jetzt nicht mehr übersehen.",name:"Hochzeitsplanung zu zweit, Berlin"}]},{slug:"dentists",title:"KI für Zahnärzte: weniger Ausfälle, nie klinisch — KI-Beratung Berlin",metaDescription:"Recall-Erinnerungen, kurzfristig nachbesetzte Termine, Diktate als Karteieinträge zur Bestätigung. Keine Diagnose, keine Bildbefundung. Patientendaten bleiben in der Praxis.",label:"Zahnärzte",headline:"Nichts Klinisches. Keine Ausnahmen, und wir haben deswegen Aufträge abgelehnt.",story:["Zwei inhabergeführte Zahnarztpraxen: eine mit drei Behandlungszimmern, eine Einzelpraxis mit zwei Angestellten. Keine von beiden wollte KI. Die eine wollte aufhören, jeden Monat 4.000 € durch Terminausfälle zu verlieren. Die andere wollte aufhören, um 20 Uhr noch Karteieinträge zu schreiben.","In der ersten Praxis geht es um die Recall-Liste: Patienten, deren Kontrolle fällig ist und die still nie wiederkommen, weil das Erinnern jemandes Nachmittag kostet und niemand diesen Nachmittag hat. In der zweiten um die Dokumentation — Notizen, zwischen zwei Patienten diktiert und nach Praxisschluss ausformuliert, dazu die Heil- und Kostenpläne, die Patienten nicht verstehen und deshalb nicht annehmen."],machinery:["Die Recall-Liste: wer ist fällig, wie wurde er kontaktiert, was hat er geantwortet","Terminerinnerungen und die Rückbestätigung durch den Patienten","Ausgefallene Termine aus einer Kurzfristliste nachbesetzen","Diktate in strukturierte Karteieinträge im Format der Praxis bringen","Die verständliche Erläuterung eines bereits genehmigten Heil- und Kostenplans samt Kosten","Abrechnungspapier: BEMA/GOZ-Positionen, Kassenanträge, offene Posten nachhalten","Dienstplan, Sterilisationsprotokolle, Bestände und die Unterlagen, die die Praxisbegehung verlangt"],judgement:["Diagnose. Jeder Teil davon","Der Behandlungsplan","Was man einem verängstigten Patienten sagt","Ob überhaupt behandelt wird"],builds:[{name:"Recall-Erinnerungen",text:"Fällige Patienten werden erkannt und planmäßig erinnert — erst per Nachricht, dann per Brief, dann über eine Anrufliste für die Rezeption. In der ersten Praxis gingen die Ausfälle um gut die Hälfte zurück, und die Recall-Lücke schloss sich innerhalb von vier Monaten. Reine Arithmetik, kein klinischer Inhalt — und es hat alles Übrige bezahlt."},{name:"Nachbesetzung ausgefallener Termine",text:"Um 09:40 wird ein Termin frei; die Kurzfristliste bekommt ihn automatisch der Reihe nach angeboten. Leere Stühle sind der größte Verlust, den eine Praxis zurückholen kann, und der Ablauf ist reine Routine."},{name:"Diktat zu Karteieintrag",text:"Der Zahnarzt spricht; der Eintrag erscheint in der Struktur der Praxis. Gelesen und bestätigt wird jeder einzelne, bevor er in die Akte geht. Nichts gelangt unbestätigt in eine Patientenakte, nie."},{name:"Das Patientenblatt",text:"Aus einem bereits genehmigten Plan eine verständliche Fassung: was passiert, in welcher Reihenfolge, was die Kasse trägt, was der Patient zahlt und welche Alternativen es gibt — die Alternativen so, wie der Zahnarzt sie vorgibt. Die Annahmequote stieg merklich, aus dem unspektakulären Grund, dass Menschen zu Dingen Nein sagen, die sie nicht verstehen."},{name:"Die Begehungsmappe",text:"Sterilisationsprotokolle, Wartungstermine und Schulungsnachweise laufend gesammelt statt in Panik vor der Begehung."}],stops:{title:"Keine Diagnose, keine Bildbefundung, keine Triage — und kein Eintrag ohne Bestätigung.",text:["Kein Diagnosevorschlag, kein Befunden eines Röntgenbilds oder OPG. Keine Behandlungsempfehlung, keine Rangfolge von Optionen, keine Prognose. Keine Symptomtriage, nicht einmal ein Telefonleitfaden, der nach Dringlichkeit sortiert — denn ein falsch einsortierter Abszess ist ein echter Schaden. Keine Patientennachricht zu einem klinischen Thema geht raus, ohne dass der Zahnarzt sie gelesen hat.","Und die Datenregeln, die streng sind: Patientendaten sind besondere Kategorien nach Artikel 9 DSGVO. Alles Klinische bleibt im Praxissystem, pseudonymisiert überall dort, wo es das System verlassen muss, Verarbeitung in der EU mit AV-Vertrag, kein Training auf Patienteninhalten, Aufbewahrung nach der Aufbewahrungspflicht und jeder Zugriff protokolliert. Wo ein Ablauf diese Bedingungen nicht erfüllen kann, wird er nicht gebaut."]},proof:"Ausfallquote. Recall-Lücke — überfällige, noch nicht kontaktierte Patienten. Leere Stuhlstunden pro Woche. Dokumentationsminuten nach Praxisschluss. Annahmequote bei Heil- und Kostenplänen.",refuse:"Alles, was in Richtung klinischer Entscheidungshilfe, Symptomtriage oder Bildbefundung geht. Beide Praxen haben nach Bildbefundung gefragt, beide haben die Antwort akzeptiert. Der Weg dafür existiert — er führt über die Medizinproduktezulassung — und er führt nicht über uns.",cost:"Jeden Eintrag lesen und bestätigen, bevor er in die Akte geht. Was ohnehin die rechtliche Pflicht ist.",quotes:[{text:"Ich wollte keine KI, ich wollte aufhören, viertausend Euro im Monat an leere Stühle zu verlieren. Er hat zwei Tage an unserer Rezeption gesessen, und dort hätte ich nicht erwartet, hinzuschauen. Recall und die Kurzfristbesetzung kamen zuerst, überhaupt nichts Klinisches, und die Ausfälle sind binnen eines Quartals um mehr als die Hälfte gesunken. Das hat alles Weitere bezahlt und das Vertrauen dafür verdient.",name:"Praxisinhaber, Praxis mit drei Behandlungszimmern, Berlin"},{text:"Notizen werden zwischen Patienten diktiert und in unserer eigenen Struktur verschriftlicht, und ich bestätige jede einzelne, bevor sie in die Akte geht — was ohnehin die rechtliche Pflicht ist. Ich habe nach OPG-Befundung gefragt, und er hat nein gesagt und erklärt, dass der Weg dafür über die Medizinproduktezulassung führt und nicht über ihn. Drei Anbieter haben mir das Gegenteil erzählt — seine Antwort ist der Grund, warum ich dem Rest geglaubt habe.",name:"Zahnärztin, Einzelpraxis"}]},{slug:"team-leaders",title:"KI für Teamleitungen: Überblick, keine Bewertung — KI-Beratung Berlin",metaDescription:"Ein privates Protokoll je Teammitglied, ein Vorbereitungsblatt vor jedem Einzelgespräch, Feedback aus Ihren Notizen, ein Kalender-Check. Keine Bewertungen, keine Überwachung.",label:"Teamleitungen",headline:"Es ordnet, was Sie beobachtet haben. Es bewertet niemanden.",story:["Eine Person führt elf Menschen in einer Engineering-Organisation, eine andere sechs im Kundenservice. Beide wurden befördert, weil sie in dem Job hervorragend waren, den sie jetzt nicht mehr machen, beide haben nie eine Schulung dafür bekommen, und beide ertrinken still in dem Papierkram, den Personalführung mit sich bringt.","Vorbereitung — oder vielmehr ihr Fehlen. Elf Einzelgespräche (1:1) alle zwei Wochen, von denen jedes mit „Letztes Mal sagtest du X, wie ist es gelaufen?“ beginnen sollte und stattdessen damit beginnt, dass die Führungskraft still versucht, sich zu erinnern. Dann das Schreiben: Feedback, das konkret sein muss und dafür Belege braucht, Belege, die irgendwo in der Erinnerung verstreut liegen, und zweimal im Jahr die Beurteilungsrunde, die zwei volle Wochenenden frisst."],machinery:["Ein laufendes Protokoll je Person führen: was besprochen, vereinbart und noch offen ist","Das Vorbereitungsblatt vor jedem Einzelgespräch — letzte Vereinbarungen, ihr Stand, offene Punkte","Ihre groben Notizen in konkretes Feedback bringen: Situation, Verhalten, Wirkung","Delegierte Aufgaben und ihre Fristen nachhalten","Den eigenen Kalender prüfen: wie viel Zeit tatsächlich ans Team geht","Die Belege für die Beurteilungsrunde aus einem Jahr eigener Notizen zusammenstellen","Einarbeitungspläne entwerfen und wiederkehrende Abläufe im Team festhalten"],judgement:["Die Beurteilung eines Menschen","Was mit jemandem wirklich los ist","Wer befördert wird, wer das schwierige Gespräch bekommt","Die Beziehung, die der ganze Job ist"],builds:[{name:"Das Personenprotokoll",text:"Eine private Datei je Teammitglied, in Ihrer Hand: was die Person zugesagt hat, was daraus geworden ist, und Ihre eigenen Beobachtungen mit Datum. Neunzig Sekunden Diktat nach jedem Einzelgespräch. Das ist das ganze System, und es verändert die Qualität Ihrer Führung stärker als alles andere, was wir bauen — denn konkret zu sein ist der Unterschied zwischen Feedback, das ankommt, und Feedback, das verpufft."},{name:"Das Vorbereitungsblatt",text:"Vor jedem Einzelgespräch: die Vereinbarungen vom letzten Mal, ihr Stand, was noch offen ist, was Sie selbst nachverfolgen wollten. Dreißig Sekunden Lesen ersetzen vier Minuten schlechtes Erinnern — und die Person gegenüber merkt den Unterschied."},{name:"Der Feedback-Entwurf",text:"Sie schreiben „Dienstag, das Deployment, gut gelöst“. Zurück kommt ein konkreter Absatz — Situation, Verhalten, Wirkung —, gebaut aus dieser Notiz und sonst nichts. Sie überarbeiten ihn und geben ihn persönlich."},{name:"Der Kalender-Check",text:"Einmal im Monat: wohin die Zeit tatsächlich ging. Beide Führungskräfte waren erschrocken. Eine stellte fest, dass 8% ihrer Zeit ans Team gingen und 44% an Meetings, deren Teilnahme sie nie hinterfragt hatte."},{name:"Die Beurteilungsmappe",text:"Zur Beurteilungsrunde die Notizen des Jahres je Person, geordnet. Aus zwei Wochenenden wird ein Nachmittag, und die Beurteilungen werden deutlich konkreter, weil sie auf Notizen von damals beruhen statt auf dem, was gerade noch im Kopf ist."}],stops:{title:"Es erzeugt nie eine Bewertung eines Menschen, und niemand wird vom System gemessen.",text:["Es benotet nie, erstellt keine Rangfolge, sagt nicht voraus, wer kündigen könnte, schlägt nie vor, wer zu wenig leistet, und schreibt nie das Fazit einer Beurteilung. Eine von Software erzeugte und von einer Führungskraft unterschriebene Leistungsbeurteilung ist eine Lüge, auf der dann die Laufbahn eines Menschen aufbaut.","Es greift auch nie in die Arbeit der Leute hinein. Kein Zählen von Code-Änderungen, keine Tickets pro Person, keine Analyse von Nachrichten, keine Aktivitätsüberwachung. Beide Führungskräfte hatten Zugang zu Werkzeugen, die das können; wir haben keines empfohlen. Überwachung verändert, was ein Team Ihnen erzählt, lange bevor sie verändert, was es tut — und dann sind Sie blind, ohne es zu merken. Die Personenprotokolle sind Ihre eigenen Notizen über Beschäftigte, also gelten die Betroffenenrechte der DSGVO einschließlich Auskunft: Schreiben Sie nichts, was Sie der Person nicht zeigen würden."]},proof:"Einzelgespräche, die mit einem Nachfassen statt mit einer Leerstelle beginnen: von gelegentlich zu Standard. Zeit für die Beurteilungsrunde. Anteil Ihrer Woche, der tatsächlich beim Team ist. Und ob das Feedback konkret geworden ist, was das Team vor Ihnen merkt.",refuse:"Wenn eine Führungskraft Einblick will, woran ihr Team gerade arbeitet. Das ist ein Vertrauensproblem, und Werkzeuge machen es schlimmer. Wir sagen das offen, und wir haben dieses Gespräch beide Male geführt.",cost:"Neunzig Sekunden Diktat nach jedem Gespräch.",quotes:[{text:"Ich wurde befördert, weil ich in einem Job gut war, den ich nicht mehr mache, und für den neuen hat mich niemand geschult. Neunzig Sekunden Diktat nach jedem 1:1, und jedes Gespräch beginnt jetzt mit „letztes Mal sagtest du X, wie lief das“, statt dass ich still versuche, mich zu erinnern. Mein Team hat es vor mir gemerkt. Die Beurteilungssaison ging von zwei Wochenenden auf einen Nachmittag, und die Beurteilungen sind viel spezifischer, weil sie aus Notizen entstehen, die ich damals geschrieben habe, statt aus dem, was ich im November erinnere.",name:"Engineering-Teamleitung, elf Mitarbeitende"},{text:"Das Kalender-Audit war unangenehm. Acht Prozent meiner Zeit gingen an mein Team und vierundvierzig Prozent an Meetings, deren Teilnahme ich nie hinterfragt hatte. Ich habe gefragt, ob wir Einblick hinzufügen könnten, woran die Leute tatsächlich arbeiten, und er hat nein gesagt und mir erklärt, das sei ein Vertrauensproblem, das Werkzeuge verschlimmern. Das wollte ich nicht hören, und es war das Nützlichste, was mir in dem Jahr jemand gesagt hat.",name:"Leitung Kundenservice, sechs Mitarbeitende"}]},{slug:"estate-agents",title:"KI für Makler: echte Käufer zuerst beantworten — KI-Beratung Berlin",metaDescription:"Jede Anfrage in Minuten beantwortet und nach Qualität sortiert, Exposés mit geprüften Pflichtangaben, Eigentümer wöchentlich informiert. Keine Wertermittlung, keine KI-Fotos.",label:"Immobilienmakler",headline:"Die acht echten Käufer zuerst beantworten, nicht alle neunzig.",story:["Ein selbstständiger Makler in Berlin und ein Zwei-Personen-Büro für Wohnimmobilien mit etwas Vermietung. Sie kamen mit gegensätzlichen Problemen: Der eine ertrank in Anfragen, die er nicht schnell genug beantworten konnte. Das andere schaffte es nicht, Exposés schnell genug fertigzustellen, um den Auftrag zu bekommen.","Ein Angebot geht online, und binnen 48 Stunden kommen 90 Anfragen. Vielleicht acht davon sind qualifizierte Käufer. Der Makler beantwortet sie in der Reihenfolge des Eingangs, um 22 Uhr, schlecht — und hat die Guten schon am ersten Tag verloren. Drumherum: das jedes Mal von vorn gebaute Exposé, der von Hand erstellte Besichtigungsplan und die Nachfassnachrichten nach Besichtigungen, die nie rausgehen."],machinery:["Anfragen sortieren: vollständig, Finanzierung genannt, Anforderungen passend zur Immobilie","Eingangsbestätigung und Qualifizierungsfragen binnen Minuten verschicken","Besichtigungen planen, auch Sammelbesichtigungen, mit Erinnerungen","Das Exposé zusammenstellen: Fotos, Grundriss, Energieausweisdaten, Provisionsangabe, Pflichtangaben","Die Objektbeschreibung aus den tatsächlichen Objektdaten entwerfen","Nach Besichtigungen nachfassen und Rückmeldungen einsammeln","Den Eigentümer auf dem Stand halten, mit Marktüberblick zu Vergleichsangeboten und Vermarktungsdauer"],judgement:["Wertermittlung und Preisstrategie","Welchen Käufer Sie dem Verkäufer empfehlen","Wie Sie einen Eigentümer mit unrealistischer Erwartung beraten","Die Verhandlung"],builds:[{name:"Anfragen sortieren",text:"Jede Anfrage wird binnen Minuten bestätigt, die Qualifizierungsfragen gleich dabei. Die Antworten werden in qualifiziert, unvollständig und ungeeignet einsortiert. Sie kümmern sich dann um acht Menschen statt um neunzig. Die Antwortzeit entscheidet mehr als alles andere darüber, wer den Käufer bekommt — und sie ist reine Routine."},{name:"Besichtigungen planen",text:"Qualifizierte Interessenten buchen aus Ihrer echten Verfügbarkeit und bekommen Erinnerungen. Die Ausfälle sanken um mehr als die Hälfte. Das zählt, weil ein Ausfall bei einer Sammelbesichtigung einen Platz kostet, den ein echter Käufer wollte."},{name:"Exposé zusammenstellen",text:"Objektdaten rein, rechtssicheres Dokument raus — mit geprüften Pflichtangaben, denn ein fehlender Energieausweiswert ist nach GEG bußgeldbewehrt und genau das, was ein müder Makler am Freitag vergisst. Die Portalfassungen kommen im richtigen Format gleich mit."},{name:"Beschreibung entwerfen",text:"Aus den tatsächlichen Merkmalen, in Ihrer Sprache, ohne erfundene Eigenschaften. Maklertexte haben einen verdienten Ruf, und wir tragen nichts dazu bei — hat das System keine Daten für eine Aussage, macht es die Aussage nicht."},{name:"Wöchentliches Eigentümerupdate",text:"Wöchentlich, automatisch, sachlich: Anfragen, Besichtigungen, Rückmeldungen. Beide Makler sagten, das habe die nervösen Eigentümeranrufe stärker reduziert als alles andere — denn die meisten dieser Anrufe sind die Bitte um Bestätigung, dass nichts ohne sie passiert."}],stops:{title:"Keine Wertermittlung, und nichts, was eine Immobilie falsch darstellt.",text:["In der Wertermittlung stecken Ihr fachliches Urteil und Ihr Ruf, und sie ist die Zahl, um die sich die ganze Beziehung dreht. Das System kann Vergleichsangebote sammeln und Vermarktungsdauern zeigen. Einen Preis nennt es nicht.","Zur Darstellung: keine erzeugten Bilder, kein Wegretuschieren, kein „gemütlich“ für winzig, kein erfundenes Baujahr, keine ausgelassenen Pflichtangaben. Über die Rechtsfolgen hinaus gilt: Alles Erfundene im Exposé fliegt bei der Besichtigung auf — und dann sind Sie die Person, die es geschrieben hat. Das System verhandelt auch nie und spricht mit Käufern nie über den Preis."]},proof:"Minuten bis zur ersten Antwort — von Stunden auf unter fünf. Qualifizierte Interessenten pro Angebot. Ausfallquote bei Besichtigungen. Vermarktungsdauer. Eigentümeranrufe pro Woche, sinkend.",refuse:"Jede Anfrage nach automatischer Wertermittlung oder erzeugten Objektfotos. Ebenso jede Anfrage, Käufern so automatisch zu antworten, dass es nach einem Menschen aussieht. Wenn ein Käufer mit einem System schreibt, soll er das erkennen können.",cost:"Acht gute Anfragen sorgfältig beantworten, statt durch neunzig zu scrollen. Die Objektdaten einmal sauber eintragen, damit Exposé und Beschreibung etwas Wahres haben, aus dem sie entstehen.",quotes:[{text:"Neunzig Anfragen in achtundvierzig Stunden, acht davon echt, und ich habe sie um zehn Uhr abends in Eingangsreihenfolge beantwortet und die Guten am ersten Tag verloren. Jetzt wird alles binnen Minuten bestätigt, mit den Qualifizierungsfragen dabei, und ich richte meine Aufmerksamkeit auf die acht. Die Antwortzeit entscheidet, wer den Käufer bekommt, und sie ist vollständig mechanisch — was er offenbar allen sagt.",name:"Selbstständiger Makler, Berlin"},{text:"Der Exposé-Baukasten prüft die Pflichtangaben, und der fehlende Energieausweiswert am Freitagnachmittag ist genau der Fehler, den ich schon gemacht habe. Er schreibt aus den tatsächlichen Merkmalen der Immobilie und erfindet keine Eigenschaft — was ich angesichts des Rufs meines Berufs für einen Wettbewerbsvorteil halte und nicht für eine Einschränkung. Das wöchentliche Eigentümerupdate hat die nervösen Anrufe stärker reduziert als alles andere.",name:"Zwei-Personen-Agentur, Wohnimmobilien"}]},{slug:"executives",title:"KI für Gründer-CEOs: vorbereitet in jeden Termin — KI-Beratung Berlin",metaDescription:"Postfach sortiert mit Begründung, 90 Sekunden Briefing vor jedem Termin, eine Liste Ihrer Zusagen, fertige Board-Unterlagen. Es entscheidet nie und schreibt nie als Sie.",label:"Führungskräfte",headline:"In ein Meeting gehen und wissen, was letztes Mal versprochen wurde.",story:["Der Gründer und CEO eines Unternehmens mit etwa 90 Menschen. Kein Konzernvorstand mit Stabschef und zwei Assistenzen — jemand, der Investoren noch selbst antwortet, noch in Einstellungsgespräche gezogen wird und dessen Kalender die Bedürfnisse anderer besetzt haben. Sein Anliegen war „Ich habe keine Zeit zum Denken“, und das ist nach unserer Erfahrung das einzige Anliegen, das CEOs wirklich haben.","Nicht eine verlorene Stunde — die ganze Form der Woche. Etwa 300 E-Mails am Tag, von denen vielleicht zwölf zählen. Termine, in die man kalt hineingeht, ohne zu wissen, was letztes Mal besprochen oder versprochen wurde. Board-Vorbereitung, die pro Quartal ein Wochenende frisst. Ein Lesestapel, der inzwischen rein theoretisch ist. Und die tiefere Folge: Jede Entscheidung fällt in den elf Minuten zwischen zwei Terminen, auf Basis dessen, was zufällig gerade im Raum war."],machinery:["Das Postfach in entscheiden, delegieren, lesen und ignorieren sortieren — mit sichtbarer Begründung","Das Briefing vor dem Termin: Wer ist das, was war vereinbart, was ist noch offen, worum wird es gehen","Die wöchentliche Zahlenübersicht aus den eigenen Systemen, als Veränderung statt als Stand","Die Board-Unterlagen aus denselben Quellen zusammenstellen, in fester Struktur","Den Lesestapel zusammenfassen, die Originalquellen einen Klick entfernt","Ihre Zusagen nachhalten: was, wem gegenüber, bis wann","Benannte Wettbewerber, den Markt und relevante regulatorische Entwicklungen beobachten"],judgement:["Jede Entscheidung","Strategie","Menschen","Wofür das Unternehmen da ist"],builds:[{name:"Postfach sortieren",text:"Vier Stapel jeden Morgen, jede E-Mail mit Begründung. Nichts wird gelöscht, nichts automatisch beantwortet, nichts versteckt — der Ignorieren-Stapel bleibt sichtbar und prüfbar. Denn ein CEO, der vermutet, dass das System etwas verbirgt, kontrolliert alles nach, und dann schadet das System mehr, als es hilft."},{name:"Briefing vor dem Termin",text:"Das Wertvollste auf dieser Liste, 90 Sekunden vor jedem Termin: letzter Kontakt, vereinbarte Punkte und ihr Stand, offene Fäden, die wahrscheinliche Bitte, die relevanten Zahlen. In ein Meeting zu gehen und zu wissen, was letztes Mal versprochen wurde, verändert, was darin passiert. Das allein hat den Auftrag gerechtfertigt."},{name:"Wöchentliche Zahlenübersicht",text:"Wöchentlich, aus den eigenen Systemen, aufgebaut nach dem, was sich verändert hat: was sich bewegt hat, um wie viel, gegenüber der Erwartung. Keine weitere Bildschirmseite voller Diagramme. Die braucht ein CEO nicht; er braucht etwas, das schon gemerkt hat, was wichtig ist."},{name:"Zusagenliste",text:"Was Sie zugesagt haben, in Terminen, wem gegenüber, bis wann. Gründer machen sehr viele mündliche Zusagen und erinnern sich an vielleicht die Hälfte."},{name:"Board-Unterlagen zusammenstellen",text:"Feste Struktur, aktuelle Zahlen, die Zusagen des Vorquartals und ihr Stand. Aus einem Wochenende wird ein Vormittag — und der Vormittag geht in die Erzählung, also in den Teil, der vorher eine Stunde am Ende bekam."}],stops:{title:"Es entscheidet nie und spricht nie als Sie.",text:["Keine externe Kommunikation wird in Ihrer Stimme erzeugt — nicht an Investoren, nicht an Mitarbeitende, nicht öffentlich. Ein CEO, dessen Worte sich erzeugen lassen, hat ein schwer umkehrbares Problem: Sobald es intern bekannt wird, liest jeder seine Nachrichten mit einer Frage im Hinterkopf.","Es empfiehlt nie eine Vorgehensweise in strategischen Fragen. Es trägt zusammen, was bekannt ist, markiert, was unbekannt ist, und hört auf. Die Versuchung, einem einsamen Gründer einen KI-Berater zu bauen, ist groß — und was dabei herauskommt, ist selbstsicher, plausibel und losgelöst von allem, was das System über das Unternehmen wirklich wissen kann. Und aus diesem Postfach geht nichts automatisch raus. Alles wartet auf Sie."]},proof:"Minuten pro Tag im Postfach. Termine, in die mit gelesenem Briefing gegangen wird. Eingehaltene Zusagen. Stunden Board-Vorbereitung. Und das, worum es anfangs eigentlich ging: Stunden ungestörter Denkzeit pro Woche, im Kalender zählbar und damals nahe null.",refuse:"Jede Variante eines KI-Beirats, Strategiegenerators oder Entscheidungsempfehlers. Ebenso alles, was die Stimme des CEO für externe Kommunikation erzeugt. Beides wurde gewünscht. Beides abgelehnt.",cost:"Fünfzehn Minuten jeden Morgen, um die Sortierung des Postfachs durchzusehen — im ersten Monat. Danach nichts.",quotes:[{text:"Neunzig Menschen, dreihundert E-Mails am Tag, zwölf davon relevant, und keine Stunde irgendwo, die mir gehörte. Das Kurzbriefing sind neunzig Sekunden Lesen, und es hat verändert, was in den Terminen passiert, weil ich jetzt hineingehe und weiß, was ich letztes Mal versprochen habe. Er wollte nichts bauen, das für externe Nutzung in meiner Stimme schreibt, und hat erklärt, was intern passiert, sobald Menschen das vermuten — das hatte ich nicht zu Ende gedacht. Aus meinem Postfach geht nichts automatisch raus. Ich bin von faktisch null Stunden Denkzeit pro Woche auf etwa zehn gekommen.",name:"Gründer und CEO, ~90 Beschäftigte"}]},{slug:"chefs",title:"KI für Küchenchefs: Wareneinsatz wieder bei 28,5% — KI-Beratung Berlin",metaDescription:"Rechnung fotografieren, und jedes Gericht ist neu kalkuliert. Vorbereitungslisten aus den Reservierungen, eine bestätigte Allergenmatrix. Den Teller fasst es nie an.",label:"Küchenchefs",headline:"Das System kümmert sich um Geld, Lager und Papier. Den Teller fasst es nicht an.",story:["Küchenchef und Inhaber eines kleinen Restaurants — etwa 40 Gedecke, wechselnde Karte, sechs Mitarbeitende. Er kam zu uns, weil sein Wareneinsatz binnen eines Jahres von 28% auf 34% gestiegen war und er nicht sagen konnte, warum. Und weil er nach dem Service bis Mitternacht Papierkram machte. An KI hatte er keinerlei Interesse und sagte das im ersten Satz.","Nach dem Service: die Vorbereitungslisten für morgen von Hand, die Bestellungen aus dem Gedächtnis, die Rechnungen auf einem Stapel, der Dienstplan jede Woche neu im Notizbuch. Und das, was ihn tatsächlich Geld kostete — niemand wusste mehr, was irgendetwas kostet, weil sich die Lieferantenpreise bewegt hatten und die Kartenpreise nicht."],machinery:["Lieferantenrechnungen lesen und den Preis jeder Zutat über die Zeit verfolgen","Jedes Gericht aus aktuellen Preisen kalkulieren und bei jeder Preisbewegung neu rechnen","Deckungsbeitrag und Wareneinsatzquote je Gericht und insgesamt neu berechnen","Rezepte auf die Gedecke hochrechnen und die Vorbereitungsliste aus den Reservierungen erstellen","Die Bestellung aus Sollbeständen und aktuellem Lagerstand zusammenstellen","Die Allergenmatrix je Gericht führen, aktualisiert bei jeder Rezeptänderung","Abfall erfassen und zeigen, wo er sich häuft, und den Dienstplan gegen die erwarteten Gedecke aufstellen"],judgement:["Geschmack. Ohne Ausnahme","Was auf die Karte kommt","Was mit einem Lieferanten passiert, der nachgelassen hat","Wie man eine Küche führt"],builds:[{name:"Rechnungen einlesen",text:"Rechnung fotografieren, die Zutatenpreise aktualisieren sich. Binnen sechs Wochen konnte er sehen, dass drei Lieferanten ohne ein Gespräch um 9–14% erhöht hatten und dass eine einzige Position still für den größten Teil des Anstiegs verantwortlich war. Das war das ganze Problem, und gelöst hat es Rechnen, nicht Intelligenz."},{name:"Laufende Gerichtkalkulation",text:"Jedes Gericht aus aktuellen Preisen kalkuliert, Deckungsbeitrag und Wareneinsatz je Teller aktualisieren sich von selbst. Zwei Gerichte machten beim Kartenpreis Verlust. Er hat einen Preis geändert und ein Gericht von der Karte genommen — beides waren seine Entscheidungen, keine davon hat die Software vorgeschlagen."},{name:"Vorbereitungsliste",text:"Die Reservierungen von heute Abend plus Karte plus Rezepte ergeben die hochgerechnete Vorbereitung für morgen. Aus fünfzehn Minuten Schreiben nach dem Service wird ein Ausdruck."},{name:"Allergenmatrix",text:"Je Gericht, automatisch aktualisiert bei jeder Rezeptänderung. Gesetzlich vorgeschrieben, fehleranfällig und genau das, was veraltet, sobald sich an einem Dienstag ein Rezept ändert. Jeden Eintrag bestätigt er selbst, denn die Folge eines falschen Allergeneintrags ist keine schlechte Bewertung."},{name:"Abfallprotokoll",text:"Dreißig Sekunden beim Abschließen. Nach einem Monat zeigte es ihm, wo der Verlust lag — und das war nicht dort, wo er ihn vermutet hatte."}],stops:{title:"Keine Rezepte, keine Karten, keine Ersatzvorschläge, keine unbestätigten Allergendaten.",text:["Das Essen ist das gesamte Geschäft. Ein erzeugtes Gericht ist für einen Küchenchef, dessen Ruf sein Gaumen ist, wertlos — und er hätte es ohnehin nicht benutzt.","Die Allergenregel ist hart: Die Matrix entsteht aus seinen Rezepten, aber jeder Eintrag wird vor der Nutzung von ihm bestätigt, und jede Rezeptänderung hebt die Bestätigung auf, bis er erneut bestätigt. Das Risiko der Kreuzkontamination ist eine Küchentatsache, die in keiner Rezeptdatei steht — also kann das System sie nicht kennen. Es bestellt auch nie selbst: Ein Bestellentwurf geht an ihn, und er schickt ihn ab, denn versehentlich bestellte 30 kg Steinbutt sind eine echte Woche."]},proof:"Wareneinsatzquote — von 34% zurück auf 28,5% binnen eines Quartals, und das war fast ausschließlich Sichtbarkeit. Papierkram nach dem Service, von etwa 70 auf etwa 15 Minuten. Abfall nach Kategorie. Ob die Allergenmatrix aktuell ist, was sie jetzt immer ist.",refuse:"Er fragte halb im Ernst, ob es Tagesgerichte aus Überbeständen vorschlagen könne. Wir haben die Überbestandsliste gebaut und dort aufgehört. Welche Zutaten überzugehen drohen, ist Rechnen; was man daraus macht, sind dreißig Jahre Kochen.",cost:"Jede Rechnung fotografieren, wenn sie kommt. Dreißig Sekunden Abfallprotokoll beim Abschließen. Jeden Allergeneintrag bestätigen — und nach jeder Rezeptänderung noch einmal.",quotes:[{text:"Mein Wareneinsatz war binnen eines Jahres von achtundzwanzig auf vierunddreißig Prozent gestiegen, und ich konnte nicht sagen, warum. Er hat zwei Services mitgearbeitet und den Papierkram nach dem Service mit mir gemacht, bevor er irgendetwas gebaut hat. Ich fotografiere jetzt Rechnungen, und binnen sechs Wochen konnte ich sehen, dass drei Lieferanten ohne Gespräch die Preise erhöht hatten. Zwei Gerichte machten beim Kartenpreis Verlust — eines habe ich im Preis geändert, das andere gestrichen, und die Maschine hat weder das eine noch das andere vorgeschlagen, sie hat mir nur die Rechnung gezeigt.",name:"Küchenchef und Inhaber, 40 Gedecke"}]},{slug:"volunteer-orgs",title:"KI für Vereine: Förderanträge in drei Stunden — KI-Beratung Berlin",metaDescription:"Alle wiederverwendbaren Fakten über Ihren Verein an einer Stelle, in die Struktur jedes Fördergebers gebracht. Anträge in drei Stunden statt zwei Tagen. Kostenlose Werkzeuge.",label:"Vereine",headline:"Förderanträge in drei Stunden statt zwei Tagen, mit kostenlosen Werkzeugen.",story:["Ein eingetragener Verein — rund 40 aktive Ehrenamtliche, eine Teilzeitkoordinatorin, finanziert aus kleinen Förderungen, Mitgliedsbeiträgen und Spenden. Niemand dort hat ein Technologiebudget, und die Koordinatorin macht die Arbeit von drei Personen auf 20 Wochenstunden. Dieser Auftrag war teilweise unbezahlt, und wir würden es wieder tun.","Das größte Problem sind die Förderanträge. Jeder Fördergeber will dieselben Informationen in anderer Struktur — Organisationsbeschreibung, Projektplan, Budget, Wirkungsnachweis, bisherige Förderung — und jeder Antrag kostet zwei volle Tage. Diese Tage fehlen bei der eigentlichen Arbeit, um die es dem Verein geht. Dahinter: die Dienstplanung für 40 Ehrenamtliche, die Mitgliederverwaltung, der Spenderdank und der Jahresbericht."],machinery:["Die wiederverwendbaren Fakten aktuell halten: Auftrag, Geschichte, Struktur, Personal, Finanzen, Projekte, Wirkungszahlen","Diese Fakten in die geforderte Struktur und Zeichenbegrenzung jedes Fördergebers bringen","Fristen, Berichtspflichten und Ergebnisse über alle Anträge hinweg verfolgen","Dienstplan: Verfügbarkeiten, Schichten, Erinnerungen, Lücken","Mitgliedschaft: Eintritte, Beiträge, Austritte, Beitragseinzug","Spenderdank und Spendenquittungen","Aktivitätsdaten laufend erfassen, damit der Wirkungsbericht keine Archäologie wird"],judgement:["Wofür der Verein da ist","Welchen Fördergeber Sie ansprechen und was Sie ihm versprechen","Jede Aussage über Wirkung","Ihre Beziehungen zu den Ehrenamtlichen"],builds:[{name:"Das Kerndokument",text:"Jede wiederverwendbare Tatsache über den Verein, einmal geschrieben, aktuell gehalten, mit Quelle für jede Zahl. Das Wertvollste, was wir gebaut haben — und im Kern eine gut geordnete Textdatei."},{name:"Der Antragsentwurf",text:"Sie geben die Fragen und Zeichenbegrenzungen eines Fördergebers ein. Heraus kommt ein Entwurf, der aus dem Kerndokument gebaut ist. Aus zwei Tagen werden etwa drei Stunden, und jede Aussage lässt sich auf das Kerndokument zurückführen. So wird unter Fristdruck nichts erfunden — und genau dann erfinden Organisationen Dinge."},{name:"Der Fristenkalender",text:"Antragsfristen, Berichtsfristen und was wem versprochen wurde. Versäumte Berichte sind der Weg, auf dem kleine Vereine ihre Fördergeber still verlieren."},{name:"Der Dienstplan",text:"Verfügbarkeiten rein, Schichten raus, Erinnerungen verschickt, Lücken früh sichtbar. Das war der größte wöchentliche Zeitfresser der Koordinatorin, und es ist reine Terminplanung."},{name:"Das Aktivitätsprotokoll",text:"Dreißig Sekunden nach jedem Termin: Was ist passiert, wie viele Menschen, was fiel auf. Ein Jahr später entsteht der Wirkungsbericht aus echten Aufzeichnungen statt aus einer panischen Rekonstruktion im Januar."}],stops:{title:"Keine Wirkungsaussage wird erzeugt, und keine Nachricht an Fördergeber geht automatisch raus.",text:["Jede Zahl in einem Förderantrag stammt aus dem Aktivitätsprotokoll oder der Buchhaltung. Gibt das Protokoll sie nicht her, sagt der Antrag das. Wirkung gegenüber einem Fördergeber zu übertreiben ist Betrug. Es passiert versehentlich unter Fristdruck, und ein flüssig schreibendes Werkzeug macht diesen Fehler leichter — deshalb ist der Antragsentwurf so gebaut, dass er sich weigert. Fehlt der Beleg, schreibt er „Das messen wir noch nicht“ und überlässt die Stelle einem Menschen.","Über Betreute wird nichts geschrieben. Wo der Verein mit schutzbedürftigen Menschen arbeitet, gelangen überhaupt keine personenbezogenen Daten in ein externes Werkzeug. Nur zusammengefasste Zahlen. Und alles muss auf kostenlosen oder fast kostenlosen Werkzeugen laufen und in zwei Jahren von der nächsten Person bedienbar sein — alles, was ein Abo oder eine Fachkraft braucht, wird aufgegeben."]},proof:"Stunden pro Förderantrag. Eingereichte Anträge pro Jahr — die sich etwa verdoppelt haben, und das ist der gesamte wirtschaftliche Sinn. Eingehaltene Berichtsfristen. Stunden der Koordinatorin für Verwaltung gegenüber der eigentlichen Arbeit. Ob das Aktivitätsprotokoll nach sechs Monaten noch geführt wird.",refuse:"Wenn ein Verein eine Website, ein CRM und eine Spendenplattform will. Das ist ein anderes Projekt mit laufenden Kosten, die er nicht tragen kann, und es wird binnen eines Jahres aufgegeben. Eine gut gepflegte Tabelle und ein dokumentierter Ablauf überleben die meisten Systeme, die für solche Organisationen gebaut werden.",cost:"Dreißig Sekunden nach jedem Termin für das Aktivitätsprotokoll. Das Kerndokument aktuell halten, wenn sich etwas ändert. Nichts, was jeden Monat Geld kostet.",quotes:[{text:"Ein Förderantrag hat zwei volle Tage gekostet, und diese Tage kamen aus der Arbeit, für die es den Verein überhaupt gibt. Alles Wiederverwendbare über uns liegt jetzt an einer Stelle und wird in die Struktur gebracht, die ein Fördergeber verlangt — das dauert etwa drei Stunden. Wir haben die Zahl der eingereichten Anträge verdoppelt, und das ist der gesamte wirtschaftliche Sinn. Er hat es so gebaut, dass der Antrag schreibt, dass wir es nicht messen, wenn der Beleg nicht im Aktivitätsprotokoll steht — statt mich um Mitternacht vor einer Frist eine Zahl improvisieren zu lassen.",name:"Koordinatorin, eingetragener Verein, ~40 Ehrenamtliche"}]},{slug:"research",title:"KI für die Forschung: Anträge in zehn Tagen — KI-Beratung Berlin",metaDescription:"Wiederverwendbarer Antragstext für jede Ausschreibung, ein Betreuungsprotokoll, Literatursichtung und reproduzierbare Abbildungen. Es erfindet nie eine Quellenangabe.",label:"Forschung",headline:"Zwei Professuren kamen von nahezu null Forschungsstunden auf acht bis zwölf pro Woche.",story:["Zwei sehr verschiedene Menschen mit demselben Kalenderproblem. Die Professur: neun SWS Lehrdeputat, vier bis fünfzehn Promovierende, Prüfungsausschuss, Berufungskommission und Fakultätsrat, sechs bis zehn unbezahlte Gutachten im Jahr und zwei bis drei Anträge, weil der Lehrstuhl auf Drittmitteln läuft. Eingestellt für die Forschung, forscht sie sonntags, wenn überhaupt. Und die Promovierende: Jahr drei eines WissZeitVG-Vertrags, der in Jahr vier endet, 900 ungelesene PDFs, drei geschriebene Kapitel, die nicht mehr zusammenpassen, und eine Auswertung, die ihre eigenen Abbildungen nicht mehr reproduzieren kann.","Für Professuren ist es der Antrag. Eine DFG-Sachbeihilfe braucht Stand der Forschung, Vorarbeiten, Arbeitsprogramm, Mittelbegründung, Lebenslauf, Publikationsliste in der DFG-eigenen Struktur, einen Datenmanagementplan, eine Ethikerklärung und Maßnahmen zur Chancengleichheit. Etwa sechzig Prozent dieses Textes gab es schon, in drei früheren Anträgen, in leicht falschen Formaten — und er wird trotzdem neu geschrieben, über fünf Wochen aus Abenden und Wochenenden, weil das Suchen der alten Fassung mühsamer erscheint als das Neutippen. Für Promovierende sind es sechshundert Abstracts, die gesichtet werden müssen, und später die schlimmere Frage: Welche Version der Auswertung hat auf welchem Datenstand Abbildung 3 erzeugt?"],machinery:["Literatur sichten: alles Neue in einem definierten Feld zusammentragen und nach Relevanz für eine Frage sortieren","Eine Literaturdatenbank aufräumen: Dubletten entfernen, Angaben reparieren, jede Quelle gegen ihren offiziellen Eintrag prüfen","Eine Publikationsliste in DFG-, ERC-, NSF-, Europass- oder Hausstruktur umformatieren","Den wiederverwendbaren Antragstext aktuell halten und in Struktur und Seitengrenzen einer Ausschreibung bringen","Ausschreibungen, Zwischen- und Abschlussberichte, Gutachtenzusagen und Prüfungstermine verfolgen","Das Betreuungsprotokoll für jede Promovierende führen","Bewerbungen in einem Berufungsverfahren gegen die veröffentlichten formalen Kriterien auf Vollständigkeit prüfen","Das Reproduzierbarkeitsprotokoll führen: welche Daten, welche Version der Auswertung, welche Abbildung"],judgement:["Die Forschungsfrage. Die Hypothese. Die Interpretation","Ob ein Ergebnis etwas bedeutet","Die Beurteilung eines Menschen — im Gutachten, in der Verteidigung, im Berufungsverfahren","Was begutachtet wird und zu welchem Schluss ein Gutachten kommt"],builds:[{name:"Der Antragskern",text:"Ein gepflegter Speicher: der Lebenslauf in jedem je verlangten Format, die Publikationsliste, die Beschreibung der Arbeitsgruppe, die Infrastruktur, die Vorarbeiten-Absätze je Forschungslinie mit ihren Abbildungen und Quellen, Ergebnisse früherer Projekte, die Vorlage für den Datenmanagementplan, die Chancengleichheitsmaßnahmen. Jeder Eintrag datiert und mit Quelle. Etwa zwei Wochen Aufbau, überwiegend Herausziehen aus drei alten Anträgen — und das letzte Mal, dass diese Absätze aus dem Nichts geschrieben werden."},{name:"Das Antragsgerüst",text:"Sie geben Struktur, Überschriften und Seitengrenzen einer Ausschreibung ein. Heraus kommt ein Gerüst, in dem das Kernmaterial schon in etwa der richtigen Länge an der richtigen Stelle steht und jeder Abschnitt, der eigenes Denken braucht, leer und beschriftet ist. Aus fünf Wochen werden etwa zehn Tage, und fast alle zehn gehen ins Arbeitsprogramm — den Teil, der gefördert wird."},{name:"Das Betreuungsprotokoll",text:"Eine private Datei je Promovierender: was vereinbart wurde, was geschah, Meilensteine gegen die Betreuungsvereinbarung, genannte Hindernisse. Neunzig Sekunden Diktat nach jedem Gespräch. Das würden wir zuerst einrichten, wenn wir nur eines einrichten dürften — weil Gespräche heute damit beginnen, dass beide sich zu erinnern versuchen, weil Gutachten zwei Jahre später aus dem Nichts entstehen und weil das Protokoll vier Monate früher zeigt, dass jemand still in Schwierigkeiten steckt."},{name:"Die Literatursichtung",text:"Für Promovierende: sechshundert Abstracts gegen Ein- und Ausschlusskriterien, die vorher aufgeschrieben wurden. Jede Entscheidung mit dem Kriterium festgehalten, das sie ausgelöst hat, jeder Grenzfall für Sie markiert. Für systematische Reviews folgt das PRISMA und liefert die Zahlen für das Flussdiagramm nebenbei."},{name:"Das Reproduzierbarkeitsprotokoll",text:"Welcher Datenstand, welche Version der Auswertung, welche Software-Umgebung, welche Ausgabe. Jede Abbildung trägt den genauen Befehl, der sie erzeugt hat. In Jahr eins an einem Nachmittag eingerichtet, in Jahr vier einen Monat wert."}],stops:{title:"Es erzeugt nie eine Quellenangabe und fasst nie eine Arbeit zusammen, die Sie zitieren werden.",text:["Quellen kommen aus Ihrer Literaturverwaltung und werden gegen den offiziellen Eintrag der jeweiligen Arbeit geprüft. Nichts, was Text erzeugt, darf eine Quellenangabe erzeugen — nie, unter keinem Vorwand. Erfundene Quellen sind das häufigste und zerstörerischste Versagen von Sprachmodellen in der Forschung, und eine müde Autorin erkennt sie um 23 Uhr nicht, weil sie genau richtig aussehen. Tausend Abstracts zu sichten, um vierzig Arbeiten zu finden, ist Routinearbeit; diese vierzig zu lesen ist der Beruf — die Sichtung liefert deshalb Titel, Abstracts und Links, nie eine Zusammenfassung, die als ausreichend präsentiert wird.","Kein Manuskript im Begutachtungsverfahren berührt einen externen Dienst: Peer Review ist vertraulich, und ein Manuskript ist unveröffentlichte Arbeit, die jemand anderem gehört. Das System schreibt nie das Argument, die Hypothese oder die Interpretation. Es reiht nie Bewerbungen in einem Berufungsverfahren — ein solches Verfahren ist gerichtlich überprüfbar, dokumentationspflichtig und unterliegt dem AGG; wir haben das zweimal abgelehnt. Keine Daten werden erfunden, keine Abbildung erzeugt, keine Bereinigung geschieht still: Roh bleibt roh. Jede Zusammenarbeit endet mit einer einseitigen Übersicht, die Sie behalten und die festhält, welche Aufgaben ein KI-Werkzeug genutzt haben und welche Offenlegungsregeln von Fördergebern und Verlagen gelten."]},proof:"Tage von der Ausschreibung bis zum eingereichten Antrag: typisch von fünf Wochen auf etwa zehn Arbeitstage. Eingereichte Anträge pro Jahr. Betreuungsgespräche mit schriftlichem Protokoll: von gelegentlich auf alle. Abbildungen, die sich mit einem einzigen Befehl reproduzieren lassen: alle. Und das Einzige, was wirklich zählt — Forschungsstunden pro Woche, die bei beiden Professuren von nahezu null auf acht bis zwölf gingen.",refuse:"Wenn jemand einen Textgenerator für Aufsätze will — zweimal gefragt, als „ein erster Entwurf der Einleitung“ und „nur der Related-Work-Teil“. Der Related-Work-Teil ist genau die Stelle, an der Sie zeigen, dass Sie das Feld gelesen haben. Ebenso, wenn ein Fachbereich Publikationskennzahlen pro Person will, was Überwachung im bibliometrischen Kostüm ist. Und wenn eine Promovierende eine Betreuung braucht statt eines Systems, was die traurigste Variante ist.",cost:"Zwei Wochen, um den Text aus alten Anträgen herauszuziehen und den Kern aufzubauen, einmalig. Neunzig Sekunden Diktat nach jedem Betreuungsgespräch. Und die Disziplin, die vierzig gefundenen Arbeiten zu lesen, was immer schon der Beruf war.",quotes:[{text:"Sechzig Prozent jedes Antrags existierten bereits, in drei früheren Anträgen, in leicht falschem Format, und ich habe es jeden März neu getippt, weil Suchen schwerer schien. Zwei Wochen Extraktion, und seitdem habe ich diese Seiten nicht mehr aus dem Nichts geschrieben. Eine DFG-Einreichung, die fünf Wochen dauerte, dauert jetzt etwa zehn Arbeitstage, und fast alle gehen ins Arbeitsprogramm, den Teil, der gefördert wird. Er hat nichts eine Quellenangabe erzeugen lassen — Referenzen lösen über die DOI auf oder sie erscheinen nicht — und angesichts dessen, was ich bei Kolleginnen habe passieren sehen, ist diese Regel der Grund, warum ich ihn überhaupt herangelassen habe.",name:"Professor (W3), Naturwissenschaften"},{text:"Jahr drei, neunhundert ungelesene PDFs, drei Kapitel, die nicht mehr zusammenpassten, und vierzig Minuten mit meinem Betreuer alle sechs Wochen. Die Sichtungsstrecke hat sechshundert Abstracts auf die vierzig gebracht, die ich wirklich lesen musste, und hat protokolliert, welches Kriterium jede Entscheidung erzeugt hat. Die Reproduzierbarkeit war an einem Nachmittag eingerichtet, und ich weiß jetzt, welche Skriptversion welche Abbildung gemacht hat — ein langweiliger Satz, der mich in meiner Verteidigung gerettet hat. Er hat mir außerdem freundlich gesagt, dass ich eigentlich eine Betreuung brauche, und er hatte recht.",name:"Doktorandin, Geisteswissenschaften"}]},{slug:"language-exams",title:"KI für IELTS, ÖSD und Goethe: üben, wo Punkte fehlen — KI-Coaching Berlin",metaDescription:"Ein Probetest je Kriterium bewertet, ein Fehlerregister, das Ihren wiederkehrenden Fehler benennt, Lernstunden dort, wo Sie Punkte verlieren. Es verspricht nie ein Ergebnis.",label:"Sprachprüfungen",headline:"Hören Sie auf, das zu üben, was Sie schon können.",story:["Fast niemand kommt aus Liebe zu einer Sprache. Man kommt, weil ein Dokument eine Zahl verlangt. Ein syrischer Arzt, der B2 plus Fachsprachprüfung vor der Approbation braucht. Eine Frau, die B1 für die Einbürgerung braucht und zweimal am Schreiben gescheitert ist. Ein indischer Softwareentwickler, der IELTS 7.0 für ein Visum braucht und 6.5 mit einer 6.0 im Schreiben hat. Eine Pflegekraft, deren Arbeitgeber den dritten Versuch bezahlt. Zweierlei gilt für fast alle: Die Frist kommt von außen und lässt sich nicht verschieben, und sie sind schon mindestens einmal durchgefallen.","Wer Lesen 82, Hören 78, Schreiben 51 hat, macht vier Abende die Woche Leseübungen, weil Lesen sich nach Fortschritt anfühlt und Schreiben nach Scheitern. Man kauft noch ein Testbuch, macht einen ganzen Test, wertet ihn aus, bekommt eine Zahl, fühlt sich schlecht und macht den nächsten. Nichts in dieser Schleife sagt, welcher der eigenen Sätze Punkte gekostet hat und warum. Zwölf Wochen später liegt das Ergebnis zwei Punkte neben dem letzten, und das ist wirklich verwirrend, denn man hat sehr hart gearbeitet."],machinery:["Einen Probetest nach den veröffentlichten Kriterien bewerten, ein Ergebnis je Kriterium statt einer Zahl","Jeden Fehler in einem Text oder einer Aufnahme nach Art sortieren und über die Versuche hinweg zählen","Ihre Lernstunden im Verhältnis dazu verteilen, wo die Punkte tatsächlich verloren gehen","Übungen zu genau diesen Fehlerarten erstellen, im echten Prüfungsformat","Wortschatz wiederholen, aufgebaut aus Ihren eigenen Fehlern statt aus einer Standardliste","Messen, wie Sie sprechen: Tempo, wo die Pausen liegen und wie lang sie sind, Füllwörter, Wortschatzbreite","Den Countdown-Plan gegen die Stunden bauen, die Sie wirklich haben","Anmeldung: Fristen, freie Termine im Prüfungszentrum, Ausweisanforderungen, Gebühren"],judgement:["Ob Sie bereit sind, sich anzumelden","Was eine Prüferin im Raum tatsächlich honoriert","Die Prüfungsangst, die beim dritten Versuch oft der größte Einzelfaktor ist","Ob das überhaupt die richtige Prüfung auf dem richtigen Niveau ist"],builds:[{name:"Die Diagnose",text:"Ein vollständiger Probetest unter echten Bedingungen, bewertet nach den veröffentlichten Kriterien, eines nach dem anderen. Bei IELTS Writing sind das vier getrennte Ergebnisse; bei ÖSD oder Goethe die Aufschlüsselung nach Modul und Kriterium, kein Bestanden oder Durchgefallen. Das Ergebnis ist bewusst keine Punktzahl. Hier ist jedes Kriterium, hier sind die Punkte verloren gegangen, und hier stehen Ihre eigenen Sätze neben dem Kriterium, das sie verfehlt haben. Die meisten haben das noch nie gesehen. Sie haben immer nur Zahlen gesehen."},{name:"Das Fehlerregister",text:"Jeder Fehler in jedem Text und jeder Aufnahme, sortiert und gezählt. Nach drei Texten sagt das Register etwa: Dreiundsechzig Prozent Ihrer Grammatikabzüge kommen aus einer einzigen Struktur. Oder: Sie haben in vier Aufsätzen hintereinander Punkte bei der Aufgabenerfüllung verloren und nie bei der Grammatik. Dieser eine Satz ist mehr wert als hundert Probetests, und kein Buch kann ihn liefern, weil kein Buch weiß, was genau Sie tun."},{name:"Der Lernplan",text:"Ihre verfügbaren Stunden, verteilt im Verhältnis dazu, wo die Punkte verloren gehen. Nicht gleichmäßig und nicht nach Vorliebe. Wer alles im Schreiben verliert, bekommt einen Plan mit etwa siebzig Prozent Schreiben und hasst ihn etwa zehn Tage lang. Für die starke Fertigkeit gilt eine Regel: gerade so viel Übung, dass sie hält, und keine Stunde mehr."},{name:"Der Sprech-Check",text:"Sie nehmen die echte Aufgabe unter echter Zeit auf. Zurück kommen das Transkript, die messbaren Größen (Tempo, wo die Pausen liegen und wie lang sie sind, Füllwörter, Wortschatzbreite, wiederholte Strukturen) und Ihre wiederkehrenden Fehler, ins Register eingetragen. Es misst, wie Sie sprechen. Es bewertet nicht Ihre Persönlichkeit, und das sagt es auch."},{name:"Der Countdown und die Modulfrage",text:"Von heute bis zum Prüfungstag, gegen die Stunden, die Sie wirklich haben, mit einem frischen Probetest alle drei Wochen. Dazu die Modulfrage: Mehrere dieser Prüfungen erlauben, ein einzelnes nicht bestandenes Modul allein zu wiederholen, und das kann einen Bruchteil der Gebühr bedeuten. Das Werkzeug stellt die Frage und nennt die Stelle, bei der Sie nachfragen. Die Antwort behauptet es nicht. Wir haben jemanden eine ganze Prüfung wiederholen sehen, weil ihm niemand gesagt hatte, dass er fragen soll."}],stops:{title:"Es verspricht nie ein Ergebnis, und es schreibt nie Ihren Aufsatz.",text:["Es gibt Einschätzungen je Kriterium nach den veröffentlichten Deskriptoren und kennzeichnet sie jedes Mal als Einschätzungen. Der Fehler wäre hier konkret und teuer: Wer einer vorhergesagten 7.0 glaubt, meldet sich an, zahlt die Gebühr, bucht den Visumstermin und schreibt 6.5. Das Bereitschaftssignal ist deshalb bewusst vorsichtig: drei Probetests hintereinander über dem Ziel in Ihrem schwächsten Kriterium, nicht im Durchschnitt. Und selbst dann ist es ein Signal an einen Menschen, keine Entscheidung.","Es schreibt nie Ihren Aufsatz und spricht nie für Sie, auch nicht als „Startpunkt“. Im Prüfungsraum wird nichts da sein, und wer verbesserte Texte einreicht, hat das Werkzeug gemessen statt sich selbst. Nichts berührt eine laufende Prüfung: keine Hilfsmittel während eines Tests, keine Unterstützung in einer beaufsichtigten Fernprüfung. Es werden keine offiziellen Prüfungsbögen reproduziert. Und keine Auskunft zu Aufenthalt, Visum oder Anerkennung: Ob ein Zertifikat für einen bestimmten Approbationsweg anerkannt wird, ist eine Rechtsfrage mit echten Folgen. Das Werkzeug verweist Sie an die Behörde, die Ärztekammer oder eine Anwältin."]},proof:"Nicht das Gesamtergebnis, das sich langsam bewegt und alles verbirgt. Die Bewegung in Ihrem schwächsten Kriterium, die einzige Zahl, die zählt, und die, die zwölf Wochen Selbststudium nie bewegt haben. Fehler pro hundert Wörter nach Art, über die Zeit. Wie sich Ihre Lernstunden verteilen, was typischerweise bei siebzig Prozent auf der starken Fertigkeit beginnt und sich binnen eines Monats umkehren sollte. Und ob das Fehlerregister nach acht Wochen noch geführt wird, was das Ergebnis besser vorhersagt als jeder einzelne Probetest.",refuse:"Wenn die Zeit nicht reichen kann. Wer solide A2 hat und in acht Wochen C1 will, kommt nicht dorthin, und wir nennen die ehrliche Zahl an Monaten in der ersten Stunde. Wenn das Zielniveau falsch ist, was zweimal ein niedrigeres Zertifikat oder eine andere, ebenfalls anerkannte Prüfung bedeutete. Wenn die Hürde Angst ist statt Sprache, denn Übungsdruck macht das schlimmer. Und wenn jemand das Ergebnis ohne die Sprache will, was ein kurzes Gespräch ist.",cost:"Alle drei Wochen ein vollständiger Probetest unter echten Bedingungen, unbequem und nicht verhandelbar. Zehn Minuten nach jeder Schreibaufgabe für das Register. Und etwa zehn Tage der Übung, die Sie bisher vermieden haben.",quotes:[{text:"B1 für die Einbürgerung, zweimal am Schreiben gescheitert, und beide Male hatte ich Lesen geübt, weil sich Lesen besser anfühlte. In der ersten Sitzung hat er mir meine eigenen Sätze neben den Kriterien gezeigt, die ich verfehlt hatte, und das hatte nie jemand getan — ich hatte immer nur Zahlen gesehen. Der Plan war zu siebzig Prozent Schreiben, und ich habe ihn etwa zehn Tage lang gehasst. Er hat mich außerdem beim Prüfungszentrum nachfragen lassen, ob ich nur das eine Modul wiederholen kann — dass das geht, hatte mir niemand gesagt, und es hat mir den größten Teil der Gebühr gespart.",name:"B1-Kandidatin, Berlin"},{text:"Ich brauchte 7.0 für den Visumsweg und hatte 6.5 mit einer 6.0 im Schreiben, und ich hatte vielleicht dreißig Probetests gemacht. Das Fehlerregister sagte mir, dass sechzig Prozent meiner Abzüge aus der Aufgabenerfüllung kamen und fast keine aus der Grammatik — das Gegenteil dessen, was ich angenommen und was ich geübt hatte. Er hat sich geweigert, mein Ergebnis als Versprechen vorherzusagen, und sagte erst nach drei Probetests hintereinander über dem Ziel in meinem schwächsten Kriterium, nicht im Durchschnitt, dass ich bereit sei. Ich hatte 7.5 im Schreiben.",name:"Softwareentwickler, IELTS-Kandidat"}]}]},how:{title:"Vier Schritte, jedes Mal.",steps:[{title:"Wir schauen uns Ihre echte Woche an.",text:"Zwei bis fünf Tage neben Ihrer tatsächlichen Arbeit. Kein Workshop, kein Fragebogen. Das Postfach, die Ordnernamen, die Klebezettel, der Behelf, der Ihnen ein bisschen peinlich ist. Der Behelf ist meistens die Stelle, an die das Werkzeug gehört."},{title:"Wir schreiben die Grenze auf.",text:"Eine Seite, die sagt, was das Werkzeug übernimmt und was bei Ihnen bleibt, Ihnen vorgelesen. Macht Sie etwas auf der Seite „übernimmt“ unruhig, haben Sie recht, und wir verschieben es. Diese Seite ist der Vertrag."},{title:"Wir bauen das kleinste Werkzeug, das die Aufgabe erledigt.",text:"Keine Plattform. Ein Werkzeug, das Ihnen die Routinearbeit vom Schreibtisch nimmt. Es ist in Wochen fertig, nicht in Quartalen, und es erledigt eine Sache so vollständig, dass Sie aufhören, daran zu denken."},{title:"Wir übergeben die Steuerung und gehen.",text:"Sie können die Regeln ohne uns ändern: die Filter, die Grenzwerte, die Vorlagen, die Gründe, aus denen etwas abgelehnt wird. Braucht ein Werkzeug uns dauerhaft, haben wir es falsch gebaut."}],noPrices:"Jedes Projekt ist anders, deshalb gibt es keine Preisliste. Nach dem kostenlosen Erstgespräch bekommen Sie ein klares Festpreisangebot, bevor Sie sich zu irgendetwas verpflichten. Die meisten Projekte dauern etwa vier Wochen vom ersten Besuch bis zur Übergabe."},principles:{title:"Drei Versprechen.",items:[{title:"Jede Entscheidung bleibt bei Ihnen.",text:"Das Werkzeug übernimmt die Routinearbeit. Die Entscheidung, die Diagnose, die Note, der Wert und das Urteil bleiben Ihre. Den Knopf, der sie Ihnen abnehmen würde, bauen wir nicht, und wir haben deswegen Aufträge abgelehnt."},{title:"Wir sagen laut Nein.",text:"Ist es zu wenig Arbeit, ist jeder Fall anders oder würde ein Kalender es lösen, hören Sie das statt eines Angebots. Das hat uns Projekte gekostet, und es ist der Grund, warum Menschen uns ihre Bekannten und Kollegen schicken."},{title:"Danach hängt nichts mehr an uns.",text:"Sie bekommen die Steuerung: die Filter, die Grenzwerte, die Vorlagen. Dazu eine schriftliche Seite darüber, was das Werkzeug darf und was nicht. Braucht ein Werkzeug uns dauerhaft, haben wir es falsch gebaut."}]},about:{eyebrow:`Über ${e.brand}`,title:"Praktische Werkzeuge, persönliche Betreuung.",photoAlt:`${e.name}, Inhaber von ${e.brand}`,text:[`${e.brand} hilft Praxen, Teams und Selbstständigen, die Routinearbeit vom Schreibtisch zu bekommen. Fast niemand kommt zu uns und fragt nach KI. Man kommt, weil ein Teil der Woche unerträglich geworden ist. Wir setzen uns in diese Woche, bis wir genau sehen, welcher Teil sich wiederholt und welcher das eigene Urteil braucht, und dann bauen wir nur für den Routineteil. Diese Kombination ist seltener, als sie klingt: Die meisten, die solche Werkzeuge bauen können, hören das Problem nicht, und die meisten, die das Problem hören, können nicht bauen. Wir machen beides. Wir hören zu, wie Sie ohnehin arbeiten, bauen oder erklären genau so viel, und sagen Ihnen klar, wenn KI sich für Sie nicht rechnet.`,`${e.brand} gehört ${e.name} und wird von ihm geführt. Er bringt rund acht Jahre Berufserfahrung mit, davon etwa fünf Jahre mit Schwerpunkt KI. Neben ${e.brand} betreibt er in einem Unternehmen ein KI-System, das eine echte Rechtsabteilung jeden Tag nutzt. Diese Mischung merkt man der Arbeit an: praktischer Rat in klarer Sprache, Werkzeuge, die für Ihren Betrieb gebaut sind und nicht für die Technik, und ein Inhaber, der vom ersten Gespräch bis zur Übergabe persönlich die Verantwortung für jedes Projekt trägt.`]},testimonials:{eyebrow:"Was Kunden sagen"},faq:{eyebrow:"Häufige Fragen",title:"Häufige Fragen.",items:[{q:"Brauche ich technisches Vorwissen?",a:"Überhaupt keines. Sie beschreiben Ihre Arbeit in Ihren eigenen Worten, alles Technische bleibt unser Problem. Der erste Schritt ist, dass wir uns Ihre tatsächliche Woche anschauen, kein Workshop und kein Fragebogen. Wenn Sie Ihren Beruf können, können wir zusammenarbeiten."},{q:"Trifft das Werkzeug Entscheidungen für mich?",a:"Nein, und darauf ist alles ausgelegt. Die Note bleibt bei der Lehrkraft, der Wert beim Gutachter, die Diagnose bei der Zahnärztin, die Prioritäten beim Produktmanager. Das Werkzeug übernimmt die Routinearbeit und bereitet das Material vor. Sie entscheiden. Den Knopf „Alle übernehmen“ haben wir mehr als einmal abgelehnt."},{q:"Was passiert, nachdem ich mich gemeldet habe?",a:"Wir sprechen dreißig Minuten, kostenlos, ohne Vorbereitung auf Ihrer Seite. Sie beschreiben Ihre Woche; wir sagen Ihnen ehrlich, ob sich ein Werkzeug lohnt und was es ungefähr bedeuten würde. Wenn es Sinn ergibt, bekommen Sie ein Festpreisangebot. Wenn nicht, gehen Sie mit einer klaren Empfehlung und ohne Rechnung."},{q:"Was kostet das?",a:"Es gibt keine Preisliste, weil eine Zahnarztpraxis und eine Doktorarbeit nicht dasselbe kosten. Nach dem kostenlosen Erstgespräch bekommen Sie ein klares Festpreisangebot, bevor Sie sich verpflichten. Die meisten Projekte dauern etwa vier Wochen vom ersten Besuch bis zur Übergabe."},{q:"Sind meine Daten bei Ihnen sicher?",a:"Ja, und bei regulierter Arbeit gestalten wir das zuerst, nicht zuletzt. Patientenakten, Handakten, Kinderdaten, Forschungsdaten unter Ethikvotum: Verarbeitung in der EU mit Auftragsverarbeitungsvertrag, kein Training auf Ihren Inhalten, Namen entfernt, wo immer Daten Ihre Systeme verlassen müssen, und ein vollständiges Protokoll darüber, wer was getan hat. Wo ein Ablauf diese Bedingungen nicht erfüllen kann, wird er nicht gebaut."},{q:"Was, wenn KI für mich die falsche Antwort ist?",a:"Dann hören Sie das im kostenlosen Erstgespräch, bevor Sie etwas ausgegeben haben. Das kommt oft vor. Drei der fünf Coaches, mit denen wir gearbeitet haben, brauchten ein Buchungssystem mit Erinnerungen und keine KI. Wir haben das eingerichtet, den Nachmittag berechnet und es so gesagt."},{q:"Wer macht die Arbeit eigentlich?",a:`${e.brand} ist inhabergeführt. ${e.name} trägt für jedes Projekt persönlich die Verantwortung: Die Person, mit der Sie im Erstgespräch sprechen, ist die Person, die sich Ihre Woche anschaut, das Werkzeug baut und es übergibt. Nichts wird an einen Junior weitergereicht.`},{q:"Müssen wir in Berlin sein?",a:"Nein. Das Erstgespräch ist ohnehin ein Telefonat oder Videocall, und die meiste Arbeit danach läuft über Bildschirmfreigabe. Bisherige Kunden sitzen auch in Leipzig und Brandenburg. Berlin macht nur den Teil einfacher, in dem wir uns Ihre Woche vor Ort anschauen."},{q:"Wie viel Zeit kostet mich das?",a:"Weniger, als Sie denken, und das meiste davon am Anfang. Der erste Schritt kostet Sie ein paar Tage, in denen wir zuschauen. Nach der Übergabe kostet es die meisten Kunden Sekunden statt Stunden: neunzig Sekunden Diktat nach einem Gespräch, zehn Sekunden nach einer Trainingseinheit, ein Foto von einer Rechnung."}]},contactSection:{eyebrow:"Kontakt",title:"Erzählen Sie uns, wie Ihre Woche aussieht.",lead:"Dreißig Minuten, kostenlos, ohne Vorbereitung. Wir sagen Ihnen ehrlich, welche Teile Ihrer Woche Sie abgeben können und welche nicht.",form:{subject:"Worum geht es",subjects:["Coaching für mich persönlich","Ein Werkzeug für meine Praxis oder mein Team","Ein Workshop oder ein Vortrag","Etwas anderes"],messageHint:"Ein Satz über Ihre Woche genügt. Keine Vorbereitung nötig.",emailHint:"Damit wir antworten können.",sending:"Wird gesendet…",reply:"Wir antworten innerhalb eines Werktags.",name:"Name",email:"E-Mail",message:"Nachricht",send:"Nachricht senden",success:"Vielen Dank. Wir melden uns innerhalb eines Werktags.",error:"Das hat nicht geklappt. Bitte schreiben Sie uns eine E-Mail.",note:"Lieber kein Formular? Buchen Sie ein Gespräch oder schreiben Sie uns direkt eine E-Mail."}},footer:{impressum:"Impressum",datenschutz:"Datenschutz"}};export{i as d};
